/* Darsi — contenuto ITALIANO (tradotto dal francese, lingua di riferimento).
   Fonti: 'q:S:V' = versetto, 'h:nome' = hadith, 'f:nome' = riferimento. Contenuto da far rileggere. */
'use strict';
CONTENU.it={
lecons:{
/* ===================== RAMADAN E DIGIUNO ===================== */
'r-bienvenue':{titre:"Il mese di Ramadan",
 texte:["Il Ramadan è il 9° mese del calendario musulmano, chiamato calendario dell'Egira. Questo calendario è lunare: ogni mese inizia con la comparsa della nuova falce di luna.",
  "L'anno lunare conta circa 354 giorni. Per questo il Ramadan si sposta in avanti di una decina di giorni ogni anno nel nostro calendario.",
  "È durante questo mese che è iniziata la rivelazione del Corano. Il digiuno del Ramadan è diventato obbligatorio nel 2° anno dell'Egira."],
 retenir:"Il Ramadan è il 9° mese lunare, il mese del Corano e del digiuno.",
 sources:['q:2:185','h:croissant'],
 quiz:[
  {q:"Nel calendario musulmano (dell'Egira), che posizione occupa il mese di Ramadan?",c:["Il 9° mese","Il 1° mese","Il 12° mese","Il 7° mese"],b:0,e:"Il Ramadan è il 9° mese. Il 1° mese dell'anno dell'Egira è Muharram.",s:['f:mois']},
  {q:"Su quale astro si basa il calendario musulmano (dell'Egira)?",c:["La luna","Il sole","Le stelle","Nessun astro"],b:0,e:"Ogni mese inizia con la comparsa della nuova falce di luna.",s:['q:2:189','h:croissant']},
  {q:"Perché la data del Ramadan si sposta in avanti di circa 11 giorni ogni anno?",c:["Perché l'anno lunare è più corto dell'anno solare","Perché i sapienti la spostano ogni anno","Perché l'anno dell'Egira conta 13 mesi","Perché si segue il calendario solare persiano"],b:0,e:"L'anno lunare conta circa 354 giorni, cioè circa 11 giorni in meno dell'anno solare.",s:['q:9:36']},
  {q:"Quale grande evento è iniziato durante il mese di Ramadan?",c:["La rivelazione del Corano","La costruzione della Kaaba","L'Egira verso Medina","La battaglia di Uhud"],b:0,e:"Il Corano ha cominciato a essere rivelato durante il Ramadan.",s:['q:2:185']},
  {q:"Quanti mesi conta l'anno musulmano (dell'Egira)?",c:["12","10","13","11"],b:0,e:"L'anno dell'Egira conta 12 mesi lunari.",s:['q:9:36']},
  {q:"Secondo l'hadith, a quale segno si inizia il digiuno del Ramadan?",c:["Quando si vede la nuova falce di luna","Quando si vede la luna piena","Il 15 di Shaʿbân, ogni anno","Dopo il primo venerdì che segue Shaʿbân"],b:0,e:"«Digiunate quando la vedete»: si tratta della falce di luna.",s:['h:croissant']},
  {q:"Come si chiama il mese che segue il Ramadan, il cui 1° giorno è l'Eid al-Fitr?",c:["Shawwâl","Shaʿbân","Rajab","Muharram"],b:0,e:"Il 1° di Shawwâl è il giorno dell'Eid al-Fitr.",s:['f:mois']},
  {q:"Quale mese del calendario musulmano precede direttamente il Ramadan?",c:["Shaʿbân","Shawwâl","Dhul-Hijja","Safar"],b:0,e:"Shaʿbân è l'8° mese, subito prima del Ramadan.",s:['f:mois']},
  {q:"In quale anno dell'Egira il digiuno del Ramadan è diventato obbligatorio?",c:["L'anno 2","L'anno 1","L'anno 10","L'anno 8"],b:0,e:"Il digiuno del Ramadan è stato prescritto a Medina, nell'anno 2 dell'Egira.",s:['f:jeune2']},
  {q:"Quanti giorni può durare il mese di Ramadan?",c:["29 o 30 giorni","Sempre 30 giorni","28 giorni","31 giorni"],b:0,e:"Un mese lunare dura 29 o 30 giorni, secondo la comparsa della falce di luna successiva.",s:['h:croissant']}
 ]},
'r-jeuner':{titre:"Chi deve digiunare?",
 texte:["Il digiuno del Ramadan è obbligatorio per il musulmano pubere, sano di mente e in grado di digiunare.",
  "Il malato e il viaggiatore possono non digiunare, e poi recuperare i giorni più tardi. La donna durante il ciclo mestruale non digiuna e recupera in seguito.",
  "La persona che non potrà mai digiunare, come una persona molto anziana, nutre un povero per ogni giorno mancato: è la fidya."],
 retenir:"Esistono delle facilitazioni: Allah vuole per noi la facilità.",
 sources:['q:2:184','q:2:185'],
 quiz:[
  {q:"Durante il Ramadan, cosa deve fare il viaggiatore che non ha digiunato alcuni giorni?",c:["Recuperare questi giorni più tardi","Niente di niente","Pagare una multa","Digiunare il doppio"],b:0,e:"Recupera lo stesso numero di giorni dopo il Ramadan.",s:['q:2:184']},
  {q:"Come si chiama la compensazione che consiste nel nutrire un povero per ogni giorno di digiuno mancato?",c:["La fidya","La sadaqa","La zakat al-fitr","La kaffâra"],b:0,e:"La fidya riguarda soprattutto chi non potrà mai recuperare, come le persone molto anziane.",s:['q:2:184']},
  {q:"Il digiuno del Ramadan è obbligatorio per un bambino che non ha raggiunto la pubertà?",c:["No, ma lo si può abituare","Sì, dall'età di 7 anni","Sì, ma solo il venerdì","Solo durante gli ultimi dieci giorni"],b:0,e:"Non è obbligatorio. I Compagni però abituavano i loro figli al digiuno, per esempio il giorno di ʿÂshûrâ'.",s:['h:enfants']},
  {q:"Durante il Ramadan, cosa fa la donna che ha il ciclo mestruale?",c:["Non digiuna e recupera i giorni in seguito","Digiuna comunque","Non recupera mai","Digiuna per metà giornata"],b:0,e:"Non digiuna, poi recupera i giorni mancati dopo il Ramadan.",s:['h:regles']},
  {q:"Il malato che non digiuna durante il Ramadan deve recuperare i giorni mancati?",c:["Sì, quando può","No, mai","Sì, ma il doppio","No, paga sempre una multa"],b:0,e:"Recupera un numero uguale di giorni quando ne è in grado.",s:['q:2:184']},
  {q:"La donna con il ciclo mestruale deve recuperare le preghiere che non ha fatto durante quel periodo?",c:["No, recupera solo il digiuno","Sì, tutte le preghiere","Sì, metà delle preghiere","Solo la preghiera del venerdì"],b:0,e:"Recupera il digiuno, ma non la preghiera.",s:['h:regles']},
  {q:"Secondo il versetto sul digiuno, cosa vuole Allah per i credenti?",c:["La facilità","La difficoltà","La fatica","La ricchezza"],b:0,e:"«Allah vuole per voi la facilità, non vuole per voi la difficoltà.»",s:['q:2:185']},
  {q:"Una persona molto anziana che non potrà mai più digiunare: cosa fa?",c:["Nutre un povero per ogni giorno","Digiuna comunque","Non deve fare nulla","Recupera dopo il Ramadan successivo"],b:0,e:"È la fidya: un pasto per un povero per ogni giorno non digiunato.",s:['q:2:184']},
  {q:"Per chi è obbligatorio il digiuno del Ramadan?",c:["Il musulmano pubere, sano di mente e in grado di digiunare","Tutti i bambini","Solo gli uomini","Solo chi ha fatto il hajj"],b:0,e:"Sono le condizioni stabilite dai sapienti.",s:['f:conditions']},
  {q:"Secondo il Corano, il digiuno è stato prescritto anche prima dei musulmani?",c:["Sì, a quelli che li hanno preceduti","No, mai","Solo alla gente della Mecca","Solo al popolo di Nûh"],b:0,e:"«Vi è stato prescritto il digiuno come è stato prescritto a quelli prima di voi.»",s:['q:2:183']}
 ]},
'r-rompt':{titre:"Ciò che rompe il digiuno",
 texte:["Il digiuno inizia all'alba, al momento della preghiera del Fajr, e termina al tramonto del sole, al momento della preghiera del Maghrib.",
  "Mangiare, bere o avere rapporti intimi volontariamente durante il giorno rompe il digiuno.",
  "Chi mangia o beve per dimenticanza continua il suo digiuno: resta valido."],
 retenir:"Mangiare o bere per dimenticanza non annulla il digiuno.",
 sources:['q:2:187','h:oubli'],
 quiz:[
  {q:"In quale momento della giornata inizia il digiuno del Ramadan?",c:["All'alba (Fajr)","A mezzanotte","Al sorgere del sole","A mezzogiorno"],b:0,e:"Il digiuno inizia all'alba, quando il filo bianco si distingue dal filo nero.",s:['q:2:187']},
  {q:"In quale momento si rompe il digiuno del Ramadan?",c:["Al tramonto del sole (Maghrib)","A notte fonda (ʿIshâ')","Alle 16","A metà della notte"],b:0,e:"Si rompe il digiuno appena il sole è tramontato.",s:['h:coucher']},
  {q:"Una persona che digiuna beve dell'acqua dimenticando di essere in digiuno. Cosa succede al suo digiuno?",c:["Resta valido","È annullato","Deve raddoppiarlo","Dipende dalla quantità"],b:0,e:"Completa il suo digiuno: è Allah che l'ha nutrito e dissetato.",s:['h:oubli']},
  {q:"Cosa succede se chi digiuna mangia volontariamente in pieno giorno di Ramadan?",c:["Il suo digiuno è rotto","Non cambia nulla","È permesso se è in moschea","È permesso dopo la preghiera del Dhohr"],b:0,e:"Mangiare volontariamente durante il giorno rompe il digiuno.",s:['q:2:187']},
  {q:"Secondo il Corano, fino a quando si può mangiare e bere durante le notti del Ramadan?",c:["Finché il filo bianco dell'alba si distingue dal filo nero della notte","Fino a mezzanotte","Fino al sorgere del sole","Fino alla preghiera dell'ʿIshâ'"],b:0,e:"È l'immagine del versetto 187 della sura Al-Baqara.",s:['q:2:187']},
  {q:"Nel versetto sul digiuno, cosa rappresenta «il filo bianco»?",c:["La luce dell'alba","Un vero filo di lana","La falce di luna","La prima stella della sera"],b:0,e:"Il filo bianco è la luce dell'alba, il filo nero l'oscurità della notte.",s:['q:2:187']},
  {q:"Durante il Ramadan, è permesso mangiare e bere di notte, dopo il tramonto del sole?",c:["Sì, fino all'alba","No, mai durante tutto il mese","Solo acqua","Solo dopo la preghiera delle tarâwîh"],b:0,e:"Il digiuno riguarda solo il giorno, dall'alba al tramonto del sole.",s:['q:2:187']},
  {q:"Secondo l'hadith, chi ha «nutrito e dissetato» colui che mangia o beve per dimenticanza durante il digiuno?",c:["Allah","La sua famiglia","Un angelo","Nessuno"],b:0,e:"Il suo digiuno resta valido: è Allah che l'ha nutrito e dissetato.",s:['h:oubli']},
  {q:"Durante le giornate del Ramadan, i rapporti intimi tra coniugi sono permessi?",c:["No, rompono il digiuno","Sì, in qualsiasi momento","Sì, il pomeriggio","Solo il giorno di ʿÂshûrâ'"],b:0,e:"Il versetto 187 li permette durante le notti del Ramadan; durante il giorno, rompono il digiuno.",s:['q:2:187']},
  {q:"Quale preghiera segna la fine della giornata di digiuno?",c:["La preghiera del Maghrib","La preghiera del Fajr","La preghiera del Dhohr","La preghiera dell'ʿIshâ'"],b:0,e:"Il Maghrib è la preghiera del tramonto, l'ora della rottura del digiuno.",s:['h:coucher']}
 ]},
'r-suhur':{titre:"Il suhur e l'iftar",
 texte:["Il suhur è il pasto consumato prima dell'alba. Il Profeta ﷺ ha incoraggiato a consumarlo, perché contiene una benedizione.",
  "L'iftar è la rottura del digiuno al tramonto del sole. È raccomandato non ritardarla.",
  "La sunna è rompere il digiuno con datteri freschi, altrimenti con datteri secchi, altrimenti con qualche sorso d'acqua."],
 retenir:"Suhur prima dell'alba. Iftar appena tramonta il sole, con dei datteri.",
 sources:['h:suhur','h:dattes'],
 quiz:[
  {q:"Come si chiama il pasto consumato prima dell'alba durante il Ramadan?",c:["Il suhur","L'iftar","La walîma","L'ʿaqîqa"],b:0,e:"Il suhur è il pasto di fine notte, prima del Fajr.",s:['h:suhur']},
  {q:"Secondo l'hadith, cosa contiene il pasto del suhur?",c:["Una benedizione","Un obbligo","Niente di particolare","Una prova"],b:0,e:"«Consumate il suhur, perché nel suhur c'è una benedizione.»",s:['h:suhur']},
  {q:"Con che cosa il Profeta ﷺ rompeva di preferenza il digiuno?",c:["Con dei datteri","Con latte di cammella","Con la ḥarîra","Con del pane"],b:0,e:"Datteri freschi, altrimenti datteri secchi, altrimenti qualche sorso d'acqua.",s:['h:dattes']},
  {q:"Bisogna ritardare la rottura del digiuno (l'iftar) dopo il tramonto del sole?",c:["No, è raccomandato affrettarsi","Sì, di un'ora","Sì, fino all'ʿIshâ'","Non ha alcuna importanza"],b:0,e:"È raccomandato rompere il digiuno appena il sole tramonta.",s:['h:hater']},
  {q:"Come si chiama il pasto che rompe il digiuno al tramonto del sole?",c:["L'iftar","Il suhur","Il ghusl","Il dhikr"],b:0,e:"L'iftar è la rottura del digiuno.",s:['h:hater']},
  {q:"Quando non c'erano datteri, con che cosa il Profeta ﷺ rompeva il digiuno?",c:["Qualche sorso d'acqua","Del miele","Latte di capra","Dei fichi"],b:0,e:"Datteri freschi, altrimenti secchi, altrimenti qualche sorso d'acqua.",s:['h:dattes']},
  {q:"Il Profeta ﷺ rompeva il digiuno prima o dopo la preghiera del Maghrib?",c:["Prima di pregare","Dopo aver pregato","Il giorno dopo","Dopo la preghiera dell'ʿIshâ'"],b:0,e:"Rompeva il digiuno prima di pregare, con qualche dattero.",s:['h:dattes']},
  {q:"Secondo l'hadith, finché le persone si affrettano a rompere il digiuno, restano…",c:["Nel bene","Nel dubbio","In pericolo","Senza ricompensa"],b:0,e:"«Le persone non smetteranno di essere nel bene finché si affretteranno a rompere il digiuno.»",s:['h:hater']},
  {q:"Il suhur è obbligatorio perché il digiuno sia valido?",c:["No, ma è fortemente raccomandato","Sì, altrimenti il digiuno è annullato","Sì, solo il primo giorno","È proibito"],b:0,e:"È una sunna: il Profeta ﷺ lo ha incoraggiato per la sua benedizione.",s:['h:suhur']},
  {q:"Che tipo di datteri preferiva il Profeta ﷺ per rompere il digiuno?",c:["Datteri freschi (ruṭab)","Datteri secchi (tamr)","Fichi secchi","Uvetta"],b:0,e:"Cominciava con datteri freschi; in mancanza, datteri secchi.",s:['h:dattes']}
 ]},
'r-merites':{titre:"I meriti del digiuno",
 texte:["Allah ha prescritto il digiuno affinché il credente raggiunga la pietà (taqwâ): la consapevolezza di Allah in ogni azione.",
  "Il Profeta ﷺ ha promesso il perdono dei peccati passati a chi digiuna il Ramadan con fede e sperando nella ricompensa di Allah.",
  "Alla fine del mese, ogni musulmano versa la zakat al-fitr prima della preghiera dell'Eid. Essa purifica chi ha digiunato e nutre i poveri."],
 retenir:"Il digiuno conduce alla pietà. La zakat al-fitr si versa prima della preghiera dell'Eid.",
 sources:['q:2:183','h:pardon','h:fitr'],
 quiz:[
  {q:"Secondo il Corano, con quale scopo Allah ha prescritto il digiuno?",c:["Per raggiungere la pietà (taqwâ)","Solo per purificare il corpo","Per commemorare l'Egira","Per sostituire la zakat"],b:0,e:"Il versetto che prescrive il digiuno termina con la speranza di raggiungere la pietà.",s:['q:2:183']},
  {q:"Secondo l'hadith, cosa ottiene chi digiuna il Ramadan con fede e sperando nella ricompensa di Allah?",c:["I suoi peccati passati sono perdonati","Non ha più bisogno di pregare","È esentato dalla zakat","Niente di particolare"],b:0,e:"I suoi peccati passati gli sono perdonati.",s:['h:pardon']},
  {q:"In quale momento bisogna versare la zakat al-fitr?",c:["Prima della preghiera dell'Eid al-Fitr","Un mese dopo il Ramadan","Solo all'inizio del Ramadan","In qualsiasi momento dell'anno"],b:0,e:"Il Profeta ﷺ ha ordinato di versarla prima che le persone uscissero per la preghiera dell'Eid.",s:['h:fitr']},
  {q:"Che cosa significa la parola «taqwâ»?",c:["La pietà, la consapevolezza di Allah","La pazienza (ṣabr)","La gratitudine (shukr)","Il pentimento (tawba)"],b:0,e:"La taqwâ è il timore reverenziale di Allah che spinge al bene.",s:['q:2:183']},
  {q:"Chi deve versare la zakat al-fitr?",c:["Ogni musulmano, piccolo o grande, uomo o donna","Solo i ricchi","Solo gli uomini","Solo chi ha digiunato tutto il mese"],b:0,e:"L'hadith la prescrive a ogni musulmano; il capofamiglia la versa per i suoi.",s:['h:fitr']},
  {q:"Quale quantità di cibo stabilisce l'hadith per la zakat al-fitr?",c:["Un sâʿ","Un mithqâl d'oro","Un mudd di grano","Un dirham d'argento"],b:0,e:"Un sâʿ è una misura pari a circa quattro volte il cavo delle due mani.",s:['h:fitr']},
  {q:"Quali alimenti sono citati nell'hadith della zakat al-fitr riferito da Ibn ʿUmar?",c:["Datteri o orzo","Riso o cuscus","Carne o pesce","Latte o miele"],b:0,e:"Un sâʿ di datteri o un sâʿ di orzo.",s:['h:fitr']},
  {q:"Secondo l'hadith, a quali condizioni il digiuno del Ramadan cancella i peccati passati?",c:["Con la fede e la speranza nella ricompensa di Allah","Digiunando in silenzio","Digiunando 40 giorni","Senza alcuna condizione"],b:0,e:"Bisogna digiunare con fede e sperando nella ricompensa di Allah.",s:['h:pardon']},
  {q:"Qual è lo scopo della zakat al-fitr, secondo l'hadith di Ibn ʿAbbâs?",c:["Purificare chi ha digiunato e nutrire i poveri","Finanziare la costruzione delle moschee","Sostituire il digiuno dei malati","Ricompensare l'imam delle tarâwîh"],b:0,e:"Purifica chi ha digiunato dalle sue parole futili e nutre i poveri.",s:['h:fitr_but']},
  {q:"Con quale appello inizia il versetto che prescrive il digiuno del Ramadan?",c:["«O voi che credete!»","«O uomini!»","«O Profeta!»","«O figli di Adamo!»"],b:0,e:"Il versetto 183 della sura Al-Baqara inizia con «O voi che credete!».",s:['q:2:183']}
 ]},
'r-nuits':{titre:"Le notti del Ramadan",
 texte:["Le notti del Ramadan sono l'occasione per pregare di più. La loro preghiera notturna si chiama tarâwîh. Il Profeta ﷺ ha promesso il perdono a chi prega nelle notti del Ramadan con fede e sperando nella ricompensa.",
  "Durante le ultime dieci notti raddoppiava gli sforzi: vegliava la notte in preghiera e svegliava la sua famiglia.",
  "Faceva anche l'iʿtikâf: un ritiro spirituale in moschea durante gli ultimi dieci giorni, e questo fino alla fine della sua vita."],
 retenir:"Tarâwîh, ultime dieci notti, iʿtikâf: le notti del Ramadan si vivono in preghiera.",
 sources:['h:qiyam','h:dixnuits','h:itikaf'],
 quiz:[
  {q:"Come si chiama la preghiera notturna praticata durante il Ramadan?",c:["Le tarâwîh","La preghiera del Duhâ","La preghiera dell'istikhâra","La preghiera funebre"],b:0,e:"Le tarâwîh sono la preghiera delle notti del Ramadan.",s:['h:qiyam']},
  {q:"Secondo l'hadith, cosa ottiene chi prega nelle notti del Ramadan con fede e sperando nella ricompensa?",c:["I suoi peccati passati sono perdonati","Un posto in prima fila in moschea","Non deve più digiunare","Niente di particolare"],b:0,e:"I suoi peccati passati gli sono perdonati.",s:['h:qiyam']},
  {q:"Che cos'è l'iʿtikâf?",c:["Un ritiro spirituale in moschea","Un viaggio alla Mecca","Il digiuno di ʿÂshûrâ'","Un'elemosina"],b:0,e:"Si resta in moschea per dedicarsi all'adorazione.",s:['h:itikaf']},
  {q:"In quale periodo del Ramadan il Profeta ﷺ faceva l'iʿtikâf?",c:["Gli ultimi dieci giorni","I primi dieci giorni","Solo il primo giorno","Dopo l'Eid"],b:0,e:"Lo faceva durante gli ultimi dieci giorni del Ramadan.",s:['h:itikaf']},
  {q:"Cosa faceva il Profeta ﷺ durante le ultime dieci notti del Ramadan?",c:["Vegliava in preghiera e svegliava la sua famiglia","Viaggiava","Andava a dormire prima","Smetteva di digiunare"],b:0,e:"Raddoppiava gli sforzi nell'adorazione.",s:['h:dixnuits']},
  {q:"Il Profeta ﷺ ha fatto l'iʿtikâf fino alla fine della sua vita?",c:["Sì, fino alla sua morte","No, una sola volta","No, mai","Solo alla Mecca"],b:0,e:"ʿÂ'isha riferisce che lo ha praticato finché Allah non lo ha richiamato a Sé.",s:['h:itikaf']},
  {q:"Dove si fa l'iʿtikâf?",c:["In moschea","A casa","Nella grotta di Hira","Al cimitero"],b:0,e:"Il Corano menziona coloro che sono in ritiro nelle moschee.",s:['q:2:187']},
  {q:"Quale notte molto importante si trova tra le ultime dieci notti del Ramadan?",c:["Laylat al-Qadr, la Notte del Destino","La notte dell'Egira","La notte dell'Eid al-Adha","La notte del Mawlid"],b:0,e:"Bisogna cercarla nelle notti dispari delle ultime dieci notti.",s:['h:qadr']},
  {q:"La preghiera delle tarâwîh è obbligatoria?",c:["No, è una preghiera supererogatoria molto raccomandata","Sì, come le cinque preghiere","Sì, ma solo in moschea","È proibita"],b:0,e:"Il Profeta ﷺ l'ha pregata in gruppo per alcune notti, poi ha smesso per timore che diventasse obbligatoria.",s:['h:tarawih']},
  {q:"Perché il Profeta ﷺ ha smesso di guidare le tarâwîh in gruppo dopo alcune notti?",c:["Per timore che diventassero obbligatorie","Perché era malato","Perché la moschea era troppo piccola","Perché il Ramadan era finito"],b:0,e:"Temeva che fossero rese obbligatorie per la sua comunità.",s:['h:tarawih']}
 ]},
'r-qadr':{titre:"Laylat al-Qadr, la Notte del Destino",
 texte:["Laylat al-Qadr, la Notte del Destino, è la notte in cui è iniziata la rivelazione del Corano.",
  "Allah dice che è «migliore di mille mesi». Gli angeli vi discendono, ed è pace fino all'alba. Un'intera sura le è dedicata: la sura Al-Qadr (97).",
  "La si cerca nelle ultime dieci notti del Ramadan, soprattutto nelle notti dispari, moltiplicando le preghiere e le invocazioni."],
 retenir:"Migliore di mille mesi. Da cercare nelle notti dispari delle ultime dieci notti.",
 sources:['q:97:1','q:97:3','h:qadr'],
 quiz:[
  {q:"Secondo il Corano, la Notte del Destino (Laylat al-Qadr) è migliore di quanto tempo?",c:["Mille mesi","Cento giorni","Un anno","Dieci notti"],b:0,e:"È migliore di mille mesi, cioè più di 83 anni.",s:['q:97:3']},
  {q:"Quale sura del Corano è dedicata alla Notte del Destino (Laylat al-Qadr)?",c:["Al-Qadr","Al-Fâtiha","Al-Ikhlâs","Yâ-Sîn"],b:0,e:"La sura 97, Al-Qadr, porta il nome di questa notte.",s:['q:97:1']},
  {q:"In quali notti del Ramadan bisogna cercare in via prioritaria la Notte del Destino (Laylat al-Qadr)?",c:["Le notti dispari delle ultime dieci notti","Le prime dieci notti","La prima notte","La notte dell'Eid"],b:0,e:"Le notti dispari delle ultime dieci: 21, 23, 25, 27 e 29.",s:['h:qadr']},
  {q:"Quale evento è avvenuto durante la Notte del Destino (Laylat al-Qadr)?",c:["L'inizio della rivelazione del Corano","L'Egira verso Medina","La nascita del Profeta ﷺ","Il primo pellegrinaggio"],b:0,e:"La rivelazione del Corano è iniziata durante questa notte.",s:['q:97:1']},
  {q:"Secondo la sura Al-Qadr, chi discende durante la Notte del Destino?",c:["Gli angeli e lo Spirito (Jibrîl)","I profeti","I jinn","Nessuno"],b:0,e:"Gli angeli e lo Spirito vi discendono, con il permesso del loro Signore.",s:['q:97:4']},
  {q:"Secondo la sura Al-Qadr, fino a quando la Notte del Destino è pace?",c:["Fino al sorgere dell'alba","Fino a mezzanotte","Fino alla fine del Ramadan","Fino all'Eid"],b:0,e:"«È pace e salvezza fino al sorgere dell'alba.»",s:['q:97:5']},
  {q:"Quanti versetti conta la sura Al-Qadr?",c:["5","7","3","10"],b:0,e:"La sura Al-Qadr conta 5 versetti.",s:['q:97:5']},
  {q:"Mille mesi corrispondono a circa quanti anni?",c:["Più di 83 anni","10 anni","40 anni","1000 anni"],b:0,e:"1000 mesi ÷ 12 ≈ 83 anni e 4 mesi: più di una vita intera.",s:['q:97:3']},
  {q:"Quali sono le notti dispari delle ultime dieci notti del Ramadan?",c:["21, 23, 25, 27 e 29","20, 22, 24, 26 e 28","1, 3, 5, 7 e 9","11, 13, 15, 17 e 19"],b:0,e:"Sono le notti raccomandate per cercare Laylat al-Qadr.",s:['h:qadr']},
  {q:"Quale invocazione il Profeta ﷺ ha insegnato a ʿÂ'isha per la Notte del Destino?",c:["«Allâhumma innaka ʿafuwwun tuḥibbu l-ʿafwa faʿfu ʿannî»","«Bismi Llâh»","«Allâhu akbar»","«Subḥâna Llâh»"],b:0,e:"«O Allah, Tu sei Colui che perdona, ami il perdono, perdonami dunque.»",s:['h:afw']}
 ]},
'r-aid':{titre:"L'Eid al-Fitr",
 texte:["L'Eid al-Fitr è la festa della rottura del digiuno. Cade il 1° giorno del mese di Shawwâl, subito dopo il Ramadan.",
  "Prima di uscire per la preghiera dell'Eid, il Profeta ﷺ mangiava qualche dattero, in numero dispari. La zakat al-fitr deve essere versata prima di questa preghiera.",
  "Dopo l'Eid, è raccomandato digiunare sei giorni del mese di Shawwâl: insieme al Ramadan, è come digiunare tutto l'anno."],
 retenir:"1° Shawwâl: l'Eid. Datteri prima della preghiera, poi sei giorni di Shawwâl.",
 sources:['h:aid_dattes','h:shawwal','q:2:185'],
 quiz:[
  {q:"In quale giorno cade l'Eid al-Fitr?",c:["Il 1° giorno di Shawwâl","Il 27 di Ramadan","Il 10 di Dhul-Hijja","Il 1° di Muharram"],b:0,e:"L'Eid al-Fitr segue direttamente il mese di Ramadan.",s:['f:mois']},
  {q:"Che cosa significa «Eid al-Fitr»?",c:["La festa della rottura del digiuno","La festa del sacrificio","La festa dell'Egira","La festa della nascita del Profeta ﷺ"],b:0,e:"Fitr significa la rottura del digiuno.",s:['f:aid']},
  {q:"Che cosa mangiava il Profeta ﷺ prima di uscire per la preghiera dell'Eid al-Fitr?",c:["Qualche dattero","Dei fichi","Della carne","Niente, digiunava"],b:0,e:"Non usciva il giorno dell'Eid al-Fitr senza aver mangiato qualche dattero.",s:['h:aid_dattes']},
  {q:"In quale numero il Profeta ﷺ mangiava i datteri la mattina dell'Eid al-Fitr?",c:["In numero dispari","Sempre due","Sempre sette","In numero pari"],b:0,e:"Anas riferisce che li mangiava in numero dispari.",s:['h:aid_dattes']},
  {q:"Quante feste (Eid) conta l'islam nell'anno?",c:["2","1","3","5"],b:0,e:"L'Eid al-Fitr e l'Eid al-Adha.",s:['f:aid']},
  {q:"Secondo l'hadith, quanti giorni di Shawwâl è raccomandato digiunare dopo il Ramadan?",c:["6","3","10","30"],b:0,e:"Sei giorni di Shawwâl, consecutivi o no.",s:['h:shawwal']},
  {q:"Secondo l'hadith, digiunare il Ramadan e poi sei giorni di Shawwâl equivale a cosa?",c:["Digiunare tutto l'anno","Fare il hajj","Digiunare un mese in più","Niente di particolare"],b:0,e:"È come se avesse digiunato tutto l'anno.",s:['h:shawwal']},
  {q:"Prima di quale preghiera bisogna aver versato la zakat al-fitr?",c:["La preghiera dell'Eid","La preghiera del venerdì","La preghiera del Maghrib","Le tarâwîh"],b:0,e:"Deve essere versata prima che le persone escano per la preghiera dell'Eid.",s:['h:fitr']},
  {q:"Secondo il versetto 185 della sura Al-Baqara, cosa fanno i credenti una volta completato il numero dei giorni del Ramadan?",c:["Proclamano la grandezza di Allah","Ricominciano a digiunare","Fanno l'iʿtikâf","Partono a visitare Medina"],b:0,e:"Il versetto invita a proclamare la grandezza di Allah per la guida ricevuta: è il takbîr dell'Eid.",s:['q:2:185']},
  {q:"Qual è l'altra grande festa dell'islam, celebrata durante il pellegrinaggio?",c:["L'Eid al-Adha","L'Eid al-Fitr","Il Mawlid","Il 1° di Muharram"],b:0,e:"L'Eid al-Adha, la festa del sacrificio, cade il 10 di Dhul-Hijja.",s:['f:aid']}
 ]},

/* ===================== PILASTRI E PREGHIERA ===================== */
'p-piliers':{titre:"I cinque pilastri dell'islam",
 texte:["L'islam si basa su cinque pilastri, citati in un hadith autentico riferito da al-Bukhari e Muslim.",
  "La shahada, l'attestazione di fede. La salat, le cinque preghiere quotidiane. La zakat, l'elemosina obbligatoria. Il hajj, il pellegrinaggio alla Mecca per chi ne ha i mezzi. Il sawm, il digiuno del Ramadan.",
  "Questi cinque pilastri sono le fondamenta della pratica del musulmano, tutto l'anno."],
 retenir:"Shahada, salat, zakat, hajj, digiuno del Ramadan.",
 sources:['h:piliers'],
 quiz:[
  {q:"Quanti pilastri conta l'islam?",c:["5","3","4","6"],b:0,e:"L'islam si basa su cinque pilastri.",s:['h:piliers']},
  {q:"Come si chiama il digiuno in arabo?",c:["Sawm (o siyâm)","Salat","Zakat","Hajj"],b:0,e:"Il digiuno si dice sawm o siyâm; è la parola del versetto che lo prescrive.",s:['q:2:183']},
  {q:"Per chi è obbligatorio il pellegrinaggio alla Mecca (hajj)?",c:["Per chi ne ha i mezzi, una volta nella vita","Per tutti, ogni anno","Solo per gli uomini","Solo durante il Ramadan"],b:0,e:"Il hajj è obbligatorio una volta nella vita, per chi ne ha la capacità fisica ed economica.",s:['q:3:97']},
  {q:"Quante preghiere obbligatorie compie un musulmano ogni giorno?",c:["5","3","7","2"],b:0,e:"Fajr, Dhohr, ʿAsr, Maghrib e ʿIshâ'.",s:['h:cinq']},
  {q:"Qual è il primo pilastro dell'islam?",c:["La shahada, l'attestazione di fede","Il digiuno","Il hajj","La zakat"],b:0,e:"La shahada è citata per prima nell'hadith.",s:['h:piliers']},
  {q:"Quale pilastro dell'islam è l'elemosina obbligatoria?",c:["La zakat","La salat","Il sawm","La shahada"],b:0,e:"La zakat si versa ogni anno sui beni che raggiungono una soglia.",s:['h:piliers']},
  {q:"Quale pilastro dell'islam si pratica durante il mese di Ramadan?",c:["Il digiuno (sawm)","Il hajj","La zakat","La shahada"],b:0,e:"Il digiuno del Ramadan è uno dei cinque pilastri.",s:['h:piliers']},
  {q:"Quale pilastro dell'islam consiste nel recarsi alla Mecca?",c:["Il hajj","La salat","Il sawm","La zakat"],b:0,e:"Il hajj è il pellegrinaggio alla Casa sacra.",s:['q:3:97']},
  {q:"Secondo l'hadith, quante volte nella vita il hajj è obbligatorio?",c:["Una sola volta","Ogni anno","Tre volte","Sette volte"],b:0,e:"Il Profeta ﷺ ha precisato che non era obbligatorio ogni anno.",s:['h:hajj_une']},
  {q:"Quale Compagno ha riferito l'hadith dei cinque pilastri dell'islam?",c:["ʿAbdallah ibn ʿUmar","Abû Bakr","Bilâl","Khâlid ibn al-Walîd"],b:0,e:"L'hadith è riferito da Ibn ʿUmar.",s:['h:piliers']}
 ]},
'p-shahada':{titre:"La shahada, l'attestazione di fede",
 texte:["La shahada è l'attestazione di fede: «Ash-hadu an lâ ilâha illâ Llâh, wa ash-hadu anna Muḥammadan rasûlu Llâh».",
  "Significa: «Attesto che non c'è divinità all'infuori di Allah, e attesto che Muhammad è il Messaggero di Allah.»",
  "È il primo pilastro: con essa si entra nell'islam. Afferma l'unicità di Allah, il tawḥîd, riassunta nella sura Al-Ikhlâs."],
 retenir:"Lâ ilâha illâ Llâh, Muḥammadun rasûlu Llâh.",
 sources:['q:47:19','q:48:29','h:piliers'],
 quiz:[
  {q:"Quale pilastro dell'islam è l'attestazione di fede?",c:["La shahada","La salat","La zakat","Il hajj"],b:0,e:"La shahada è il primo pilastro.",s:['h:piliers']},
  {q:"Che cosa significa «lâ ilâha illâ Llâh»?",c:["Non c'è divinità all'infuori di Allah","Allah è il più grande","Gloria ad Allah","Nel nome di Allah"],b:0,e:"È la prima parte della shahada.",s:['q:47:19']},
  {q:"Che cosa significa «Muḥammadun rasûlu Llâh»?",c:["Muhammad è il Messaggero di Allah","Muhammad è un angelo","Muhammad è il primo uomo","Muhammad è un re"],b:0,e:"È la seconda parte della shahada.",s:['q:48:29']},
  {q:"Come si chiama la fede nell'unicità di Allah?",c:["Il tawḥîd","Il hajj","La sunna","Il fiqh"],b:0,e:"Il tawḥîd è il cuore della fede musulmana.",s:['q:112:1']},
  {q:"Quale sura riassume l'unicità di Allah in quattro versetti?",c:["Al-Ikhlâs","Al-Fâtiha","Al-Kawthar","An-Nâs"],b:0,e:"La sura 112, Al-Ikhlâs.",s:['q:112:1']},
  {q:"Di quante parti si compone la shahada?",c:["Due: l'unicità di Allah e il messaggio di Muhammad ﷺ","Una sola","Cinque","Sette"],b:0,e:"Si attesta l'unicità di Allah, poi che Muhammad ﷺ è il Suo Messaggero.",s:['h:piliers']},
  {q:"Secondo la sura Al-Ikhlâs, Allah ha generato o è stato generato?",c:["Né l'uno né l'altro","Entrambe le cose","Ha generato","È stato generato"],b:0,e:"«Non ha generato, non è stato generato.»",s:['q:112:3']},
  {q:"Che cosa significa «Ash-hadu» all'inizio della shahada?",c:["Attesto","Prego","Digiuno","Perdono"],b:0,e:"Ash-hadu significa «attesto, testimonio».",s:['f:shahada']},
  {q:"Che cosa fa una persona per entrare nell'islam?",c:["Pronuncia la shahada con convinzione","Digiuna un mese","Fa il hajj","Impara l'arabo"],b:0,e:"La shahada pronunciata sinceramente fa entrare nell'islam.",s:['f:shahada']},
  {q:"Che cosa dice il Corano di Muhammad ﷺ nella sura Âl ʿImrân, versetto 144?",c:["Non è che un messaggero, altri messaggeri sono passati prima di lui","È eterno","È un angelo","È il primo profeta"],b:0,e:"Muhammad ﷺ è un essere umano e un messaggero, come quelli che lo hanno preceduto.",s:['q:3:144']}
 ]},
'p-priere':{titre:"La preghiera, cinque appuntamenti al giorno",
 texte:["Il musulmano prega cinque volte al giorno: Fajr all'alba, Dhohr a mezzogiorno, ʿAsr nel pomeriggio, Maghrib al tramonto del sole e ʿIshâ' la notte.",
  "Ogni preghiera conta un numero preciso di unità (rakʿât): 2 per il Fajr, 4 per il Dhohr, 4 per l'ʿAsr, 3 per il Maghrib e 4 per l'ʿIshâ'.",
  "Si prega rivolti verso la Kaaba, alla Mecca: è la qibla. L'ora di ogni preghiera è annunciata dall'adhân. Il venerdì, la preghiera del Dhohr è sostituita dalla preghiera del venerdì (Jumuʿa)."],
 retenir:"Fajr 2, Dhohr 4, ʿAsr 4, Maghrib 3, ʿIshâ' 4 — rivolti verso la qibla.",
 sources:['q:4:103','f:rakat','q:2:144'],
 quiz:[
  {q:"Quante unità (rakʿât) conta la preghiera obbligatoria del Fajr?",c:["2","3","4","1"],b:0,e:"La preghiera del Fajr conta 2 rakʿât.",s:['f:rakat']},
  {q:"Quante unità (rakʿât) conta la preghiera obbligatoria del Maghrib?",c:["3","2","4","5"],b:0,e:"Il Maghrib è l'unica preghiera obbligatoria di 3 rakʿât.",s:['f:rakat']},
  {q:"Verso quale direzione si rivolgono i musulmani per pregare?",c:["Verso la Kaaba, alla Mecca","Verso Gerusalemme","Verso Medina","Verso est"],b:0,e:"Questa direzione si chiama qibla.",s:['q:2:144']},
  {q:"Come si chiama il richiamo che annuncia l'ora della preghiera?",c:["L'adhân","L'iqâma","Il duʿâ'","Il dhikr"],b:0,e:"L'adhân annuncia l'ora; l'iqâma annuncia l'inizio della preghiera in gruppo.",s:['h:adhan']},
  {q:"Come si chiama la preghiera obbligatoria fatta all'alba?",c:["Il Fajr","Il Dhohr","L'ʿAsr","L'ʿIshâ'"],b:0,e:"Il Fajr si prega tra l'alba e il sorgere del sole.",s:['f:rakat']},
  {q:"Quante unità (rakʿât) conta la preghiera obbligatoria del Dhohr?",c:["4","2","3","5"],b:0,e:"Il Dhohr conta 4 rakʿât.",s:['f:rakat']},
  {q:"Quante unità (rakʿât) obbligatorie si contano in totale nelle cinque preghiere di una giornata?",c:["17","15","20","12"],b:0,e:"2 + 4 + 4 + 3 + 4 = 17 rakʿât.",s:['f:rakat']},
  {q:"Secondo il Corano, come è stata prescritta la preghiera ai credenti?",c:["In orari stabiliti","Una volta alla settimana","Quando lo si desidera","Solo durante il Ramadan"],b:0,e:"«La Salat è, per i credenti, una prescrizione in tempi stabiliti.»",s:['q:4:103']},
  {q:"Quale preghiera collettiva si svolge ogni venerdì al posto del Dhohr?",c:["La preghiera del venerdì (Jumuʿa)","La preghiera dell'Eid","Le tarâwîh","La preghiera per la pioggia"],b:0,e:"Il Corano invita a recarsi al ricordo di Allah il venerdì.",s:['q:62:9']},
  {q:"Secondo l'hadith, in occasione di quale evento sono state prescritte le cinque preghiere?",c:["Il Viaggio notturno (al-Isrâ' wa l-Miʿrâj)","La battaglia di Badr","L'Egira","La conquista della Mecca"],b:0,e:"Furono prescritte cinquanta preghiere, poi ridotte a cinque.",s:['h:cinq']}
 ]},
'p-ablutions':{titre:"L'abluzione e la Fâtiha",
 texte:["Prima di pregare, il musulmano si purifica con l'acqua: è l'abluzione (wudû'). Senza acqua, si fa il tayammum con terra pulita.",
  "Si lava il viso, le mani e gli avambracci fino ai gomiti, si passano le mani bagnate sulla testa, poi si lavano i piedi fino alle caviglie.",
  "In ogni unità della preghiera si recita la sura Al-Fâtiha, «l'Aprente», la prima sura del Corano, che conta 7 versetti."],
 retenir:"Nessuna preghiera senza abluzione, nessuna preghiera senza la Fâtiha.",
 sources:['q:5:6','q:1:2','h:fatiha'],
 quiz:[
  {q:"Come si chiama la purificazione fatta con l'acqua prima della preghiera?",c:["L'abluzione (wudû')","Il digiuno","La zakat","L'iʿtikâf"],b:0,e:"Il wudû' purifica prima della preghiera.",s:['q:5:6']},
  {q:"Quale sura si recita in ogni unità (rakʿa) della preghiera?",c:["Al-Fâtiha","Al-Ikhlâs","Al-Baqara","Yâ-Sîn"],b:0,e:"Al-Fâtiha, «l'Aprente», si recita in ogni rakʿa.",s:['h:fatiha']},
  {q:"Con quale frase inizia la sura Al-Fâtiha?",c:["Bismi Llâhi r-Raḥmâni r-Raḥîm","Qul huwa Llâhu aḥad","Allâhu akbar","Subḥâna Llâh"],b:0,e:"«Nel nome di Allah, il Compassionevole, il Misericordioso.»",s:['q:1:1']},
  {q:"Secondo il Corano, fino a dove si lavano le braccia durante l'abluzione?",c:["Fino ai gomiti","Fino ai polsi","Fino alle spalle","Solo le dita"],b:0,e:"Il versetto 6 della sura Al-Mâ'ida lo precisa.",s:['q:5:6']},
  {q:"Secondo il Corano, che cosa si fa sulla testa durante l'abluzione?",c:["Ci si passano sopra le mani bagnate","La si lava interamente tre volte","La si copre con un turbante","Si versa acqua sulla nuca"],b:0,e:"È il masḥ: passare le mani bagnate sulla testa.",s:['q:5:6']},
  {q:"Che cosa si fa quando non si trova acqua per purificarsi prima della preghiera?",c:["Il tayammum, con terra pulita","Non si prega","Si aspetta il giorno dopo","Si prega senza purificazione"],b:0,e:"Lo stesso versetto prevede il tayammum quando manca l'acqua.",s:['q:5:6']},
  {q:"Secondo l'hadith, Allah accetta la preghiera di chi ha perso l'abluzione senza rifarla?",c:["No, finché non rifà l'abluzione","Sì, sempre","Sì, il venerdì","Solo la preghiera del Fajr"],b:0,e:"La preghiera è accettata solo dopo aver rifatto l'abluzione.",s:['h:wudu']},
  {q:"Quanti versetti conta la sura Al-Fâtiha?",c:["7","5","10","3"],b:0,e:"È chiamata «i sette versetti ripetuti».",s:['q:15:87']},
  {q:"Che cosa significa «Al-ḥamdu li-Llâhi rabbi l-ʿâlamîn»?",c:["Lode ad Allah, Signore dei mondi","Allah è il più grande","Non c'è divinità all'infuori di Allah","Mi rifugio presso Allah"],b:0,e:"È il 2° versetto della Fâtiha.",s:['q:1:2']},
  {q:"Secondo l'hadith, che valore ha la preghiera di chi non recita la Fâtiha?",c:["Non è valida","Conta il doppio","È valida","Conta a metà"],b:0,e:"«Non c'è preghiera per chi non recita la Fâtiha.»",s:['h:fatiha']}
 ]},
'p-zakat':{titre:"La zakat, l'elemosina obbligatoria",
 texte:["La zakat è l'elemosina obbligatoria, uno dei cinque pilastri dell'islam. Il suo nome evoca la purificazione e la crescita: purifica i beni e aiuta i più bisognosi.",
  "Riguarda chi ha risparmi che raggiungono una soglia minima (il niṣâb) e restano in suo possesso per un intero anno lunare. Per il denaro, è del 2,5%.",
  "Il Corano cita otto categorie di beneficiari, tra cui i poveri e i bisognosi. La sadaqa, invece, è un'elemosina volontaria, possibile in qualsiasi momento."],
 retenir:"Zakat: 2,5% dei risparmi che raggiungono il niṣâb per un anno lunare.",
 sources:['q:9:60','q:9:103','f:zakat'],
 quiz:[
  {q:"Quale pilastro dell'islam è l'elemosina obbligatoria?",c:["La zakat","La sadaqa","Il hajj","Il sawm"],b:0,e:"La zakat è obbligatoria; la sadaqa è volontaria.",s:['h:piliers']},
  {q:"Qual è l'aliquota della zakat sul denaro risparmiato?",c:["2,5%","10%","20%","5%"],b:0,e:"Cioè un quarantesimo dei risparmi.",s:['f:zakat']},
  {q:"Come si chiama la soglia minima di ricchezza a partire dalla quale la zakat è dovuta?",c:["Il niṣâb","Il sâʿ","La fidya","Il ḥawl"],b:0,e:"Al di sotto del niṣâb, la zakat non è obbligatoria.",s:['f:zakat']},
  {q:"Per quanto tempo i risparmi devono essere posseduti perché la zakat sia dovuta?",c:["Un anno lunare","Un mese","Dieci anni","Solo il mese di Ramadan"],b:0,e:"È il ḥawl: un intero anno lunare.",s:['f:zakat']},
  {q:"Secondo il Corano, quante categorie di persone possono ricevere la zakat?",c:["8","5","3","12"],b:0,e:"Il versetto 60 della sura At-Tawba ne cita otto.",s:['q:9:60']},
  {q:"Chi fa parte dei beneficiari della zakat citati nel Corano?",c:["I poveri e i bisognosi","I più ricchi","I commercianti","Gli imam delle moschee"],b:0,e:"I poveri e i bisognosi sono citati per primi.",s:['q:9:60']},
  {q:"Qual è la differenza tra la zakat e la sadaqa?",c:["La zakat è obbligatoria, la sadaqa è volontaria","Non ce n'è nessuna","La sadaqa è obbligatoria","La zakat è proibita"],b:0,e:"La sadaqa si può dare in qualsiasi momento e in qualsiasi quantità.",s:['f:zakat']},
  {q:"Nel Corano, con quale atto la zakat è citata molto spesso?",c:["La preghiera","Il digiuno","Il pellegrinaggio","L'abluzione"],b:0,e:"«Eseguite la Salat e versate la Zakat»: la formula ritorna molte volte.",s:['q:2:43']},
  {q:"Nell'ordine dell'hadith dei pilastri, in che posizione viene la zakat?",c:["La 3ª","La 1ª","La 5ª","La 2ª"],b:0,e:"Shahada, preghiera, zakat, hajj, digiuno del Ramadan.",s:['h:piliers']},
  {q:"Che cosa evoca la parola «zakat» in arabo?",c:["La purificazione e la crescita","La pazienza","La vittoria","La luce"],b:0,e:"Il Corano dice che l'elemosina purifica (tuṭahhiruhum) e fa crescere nel bene (tuzakkîhim).",s:['q:9:103']}
 ]},
'p-hajj':{titre:"Il hajj, il pellegrinaggio",
 texte:["Il hajj è il pellegrinaggio alla Mecca, uno dei cinque pilastri dell'islam. È obbligatorio una volta nella vita per chi ne ha i mezzi fisici ed economici.",
  "Si svolge durante il mese di Dhul-Hijja. Il pellegrino entra nello stato di sacralizzazione (iḥrâm), fa sette giri intorno alla Kaaba (ṭawâf) e sette percorsi tra Ṣafâ e Marwa (saʿy). Il momento più importante è la sosta ad ʿArafa, il 9 di Dhul-Hijja.",
  "Il giorno dopo, i musulmani di tutto il mondo celebrano l'Eid al-Adha, la festa del sacrificio, in ricordo di Ibrahim."],
 retenir:"Una volta nella vita. ʿArafa il 9 di Dhul-Hijja, l'Eid al-Adha il 10.",
 sources:['q:3:97','q:22:27','h:hajj_pardon'],
 quiz:[
  {q:"In quale città si fa il hajj?",c:["La Mecca","Medina","Gerusalemme","Taif"],b:0,e:"Il hajj si fa alla Mecca e nei suoi dintorni.",s:['q:3:97']},
  {q:"In quale mese del calendario musulmano si svolge il hajj?",c:["Dhul-Hijja","Ramadan","Muharram","Shawwâl"],b:0,e:"Il hajj si svolge dall'8 al 13 di Dhul-Hijja.",s:['f:hajj']},
  {q:"Secondo l'hadith, qual è l'elemento più importante del hajj?",c:["La sosta ad ʿArafa","La preghiera nella moschea al-Aqṣâ","La visita di Medina","La visita della grotta di Hira"],b:0,e:"«Il hajj è ʿArafa.»",s:['h:arafa']},
  {q:"Quale festa si celebra il giorno dopo il giorno di ʿArafa?",c:["L'Eid al-Adha","L'Eid al-Fitr","Il Mawlid","Il 1° di Muharram"],b:0,e:"Il 10 di Dhul-Hijja è l'Eid al-Adha.",s:['f:hajj']},
  {q:"Secondo l'hadith, come torna il pellegrino che compie il hajj senza peccato né volgarità?",c:["Come il giorno in cui sua madre lo ha messo al mondo","Più ricco","Esentato dal digiuno","Con il titolo di ḥâjj, senza altra ricompensa"],b:0,e:"Torna puro dai suoi peccati.",s:['h:hajj_pardon']},
  {q:"Quale profeta ha ricevuto l'ordine di chiamare le persone al pellegrinaggio?",c:["Ibrahim","Mûsâ","Nûh","Yûsuf"],b:0,e:"Allah ha ordinato a Ibrahim di chiamare le persone al hajj.",s:['q:22:27']},
  {q:"Come si chiama lo stato di sacralizzazione in cui entra il pellegrino?",c:["L'iḥrâm","Il wudû'","L'iʿtikâf","Il tayammum"],b:0,e:"Gli uomini indossano due pezzi di tessuto bianco non cuciti.",s:['f:hajj']},
  {q:"Come si chiamano i sette giri compiuti intorno alla Kaaba?",c:["Il ṭawâf","Il saʿy","La rakʿa","Il dhikr"],b:0,e:"Il ṭawâf si fa in sette giri, con la Kaaba alla propria sinistra.",s:['f:hajj']},
  {q:"Tra quali due colline il pellegrino compie sette percorsi?",c:["Ṣafâ e Marwa","ʿArafa e Minâ","Uhud e Thawr","Hira e Thawr"],b:0,e:"Il Corano cita Ṣafâ e Marwa tra i riti di Allah.",s:['q:2:158']},
  {q:"In ricordo di quale profeta i musulmani sacrificano un animale il giorno dell'Eid al-Adha?",c:["Ibrahim","ʿÎsâ","Mûsâ","Dâwûd"],b:0,e:"Allah riscattò il figlio di Ibrahim con un sacrificio generoso.",s:['q:37:107']}
 ]},

/* ===================== CORANO ===================== */
'c-coran':{titre:"Il Corano, parola di Allah",
 texte:["Il Corano è la parola di Allah, rivelata in arabo al Profeta Muhammad ﷺ per mezzo dell'angelo Jibrîl (Gabriele).",
  "La prima rivelazione è avvenuta nella grotta di Hira, vicino alla Mecca, quando il Profeta ﷺ aveva 40 anni. Le prime parole rivelate iniziano con «Iqra'»: «Leggi!».",
  "La rivelazione è durata circa 23 anni. Il Corano conta 114 sure; Allah si è impegnato a preservarlo."],
 retenir:"114 sure, rivelate in 23 anni. Prima parola: «Iqra'», «Leggi!».",
 sources:['q:96:1','h:hira','q:15:9'],
 quiz:[
  {q:"Quante sure conta il Corano?",c:["114","99","120","30"],b:0,e:"Il Corano conta 114 sure.",s:['f:coran']},
  {q:"Quale angelo ha trasmesso il Corano al Profeta Muhammad ﷺ?",c:["Jibrîl (Gabriele)","Mikâ'îl","Isrâfîl","Mâlik"],b:0,e:"È l'angelo Jibrîl che ha trasmesso la rivelazione.",s:['q:2:97']},
  {q:"In quale grotta il Profeta ﷺ ha ricevuto la prima rivelazione del Corano?",c:["La grotta di Hira","La grotta di Thawr","Una grotta di Medina","Una grotta di Gerusalemme"],b:0,e:"La grotta di Hira si trova sul Jabal an-Nour, vicino alla Mecca.",s:['h:hira']},
  {q:"Che cosa significa «Iqra'», la prima parola rivelata del Corano?",c:["Leggi!","Prega!","Ascolta!","Digiuna!"],b:0,e:"È l'inizio della sura Al-ʿAlaq (96).",s:['q:96:1']},
  {q:"In quanti anni circa è stato rivelato il Corano?",c:["23 anni","1 anno","40 anni","10 anni"],b:0,e:"Circa 13 anni alla Mecca e 10 anni a Medina.",s:['h:vie']},
  {q:"In quante parti (juz') è diviso il Corano per la sua lettura?",c:["30","114","7","12"],b:0,e:"Trenta parti: per esempio una al giorno durante il Ramadan.",s:['f:coran']},
  {q:"In quale lingua è stato rivelato il Corano?",c:["In arabo","In ebraico","In persiano","In aramaico"],b:0,e:"«Lo abbiamo fatto scendere, un Corano in lingua araba.»",s:['q:12:2']},
  {q:"Secondo il Corano, chi garantisce la preservazione del Corano?",c:["Allah","Solo i sapienti","I califfi","Nessuno"],b:0,e:"«Siamo Noi che abbiamo fatto scendere il Corano, e siamo Noi che ne siamo i custodi.»",s:['q:15:9']},
  {q:"Quanti anni aveva il Profeta ﷺ al momento della prima rivelazione?",c:["40 anni","25 anni","63 anni","13 anni"],b:0,e:"Ha cominciato a ricevere la rivelazione a 40 anni.",s:['h:vie']},
  {q:"Come si chiama un versetto del Corano in arabo?",c:["Una âya","Una sura","Un juz'","Un hadith"],b:0,e:"Un versetto si dice âya; un capitolo, sura.",s:['f:coran']}
 ]},
'c-sourates':{titre:"Le sure",
 texte:["Il Corano è composto da 114 sure di lunghezza molto diversa. Ognuna inizia con la basmala, tranne la sura At-Tawba.",
  "La prima è Al-Fâtiha, «l'Aprente». La più lunga è Al-Baqara, «la Vacca», con 286 versetti. La più corta è Al-Kawthar, con 3 versetti. L'ultima è An-Nâs, «gli Uomini».",
  "Le sure rivelate prima dell'Egira sono dette meccane, quelle rivelate dopo, medinesi."],
 retenir:"Prima: Al-Fâtiha. Più lunga: Al-Baqara. Più corta: Al-Kawthar. Ultima: An-Nâs.",
 sources:['q:1:1','q:108:1','q:114:1'],
 quiz:[
  {q:"Qual è la prima sura del Corano?",c:["Al-Fâtiha","Al-Baqara","An-Nâs","Al-ʿAlaq"],b:0,e:"Al-Fâtiha apre il Corano. Al-ʿAlaq contiene i primi versetti rivelati, ma è la sura 96.",s:['q:1:1']},
  {q:"Qual è la sura più lunga del Corano?",c:["Al-Baqara","Al-Fâtiha","Al-Kawthar","Yâ-Sîn"],b:0,e:"Al-Baqara, la sura 2, conta 286 versetti.",s:['f:coran']},
  {q:"Qual è la sura più corta del Corano?",c:["Al-Kawthar","Al-Ikhlâs","An-Nâs","Al-ʿAsr"],b:0,e:"Al-Kawthar, la sura 108, conta 3 versetti.",s:['q:108:1']},
  {q:"Qual è l'ultima sura del Corano?",c:["An-Nâs","Al-Falaq","Al-Ikhlâs","Al-Fâtiha"],b:0,e:"An-Nâs, «gli Uomini», è la sura 114.",s:['q:114:1']},
  {q:"Quale sura inizia con «Qul huwa Llâhu aḥad»?",c:["Al-Ikhlâs","An-Nâs","Al-Falaq","Al-Kâfirûn"],b:0,e:"«Di': Egli è Allah, l'Unico.»",s:['q:112:1']},
  {q:"Quale sura contiene il versetto «Questo è il Libro sul quale non c'è alcun dubbio»?",c:["Al-Baqara","Al-Fâtiha","Maryam","Yâ-Sîn"],b:0,e:"È il 2° versetto della sura Al-Baqara.",s:['q:2:2']},
  {q:"Quale sura porta il nome della madre di ʿÎsâ (Gesù)?",c:["Maryam","Âl ʿImrân","An-Nisâ'","Tâ-Hâ"],b:0,e:"La sura 19 porta il nome di Maryam.",s:['q:19:16']},
  {q:"Qual è l'unica sura che non inizia con «Bismi Llâhi r-Raḥmâni r-Raḥîm»?",c:["At-Tawba (sura 9)","Al-Fâtiha","An-Nâs","Al-Baqara"],b:0,e:"At-Tawba è l'unica delle 114 sure senza basmala all'inizio.",s:['f:tawba']},
  {q:"Come si chiama la formula «Bismi Llâhi r-Raḥmâni r-Raḥîm»?",c:["La basmala","La shahada","Il takbîr","La talbiya"],b:0,e:"Significa: «Nel nome di Allah, il Compassionevole, il Misericordioso».",s:['q:1:1']},
  {q:"Come si chiamano le sure rivelate alla Mecca, prima dell'Egira?",c:["Le sure meccane","Le sure medinesi","Le sure lunghe","Le sure di Taif"],b:0,e:"Quelle rivelate dopo l'Egira sono dette medinesi.",s:['f:coran']}
 ]},
'c-ikhlas':{titre:"Al-Ikhlâs e il versetto del Trono",
 texte:["La sura Al-Ikhlâs (112) riassume la fede nell'unicità di Allah: Egli è Unico, non ha generato e non è stato generato, e nessuno è uguale a Lui.",
  "Il Profeta ﷺ ha detto che equivale a un terzo del Corano.",
  "Il versetto del Trono, Âyat al-Kursî (sura 2, versetto 255), è il versetto più grande del Corano. Descrive la vita, la scienza e la potenza di Allah."],
 retenir:"Al-Ikhlâs vale un terzo del Corano. Âyat al-Kursî è il versetto più grande.",
 sources:['q:112:1','h:ikhlas','h:kursi'],
 quiz:[
  {q:"Che cosa significa «Qul huwa Llâhu aḥad»?",c:["Di': Egli è Allah, l'Unico","Nel nome di Allah","Allah è il più grande","Gloria ad Allah"],b:0,e:"È il primo versetto della sura Al-Ikhlâs.",s:['q:112:1']},
  {q:"Secondo l'hadith, la sura Al-Ikhlâs equivale a quale parte del Corano?",c:["Un terzo","La metà","Un decimo","L'intero Corano"],b:0,e:"Il Profeta ﷺ ha detto che equivale a un terzo del Corano.",s:['h:ikhlas']},
  {q:"Quanti versetti conta la sura Al-Ikhlâs?",c:["4","7","3","5"],b:0,e:"La sura Al-Ikhlâs conta 4 versetti.",s:['q:112:4']},
  {q:"Secondo la sura Al-Ikhlâs, qualcuno è uguale ad Allah?",c:["No, nessuno è uguale a Lui","Sì, gli angeli","Sì, i profeti","Sì, i jinn"],b:0,e:"«E nessuno è uguale a Lui.»",s:['q:112:4']},
  {q:"Secondo l'hadith, qual è il versetto più grande del Corano?",c:["Âyat al-Kursî, il versetto del Trono","Il primo versetto della Fâtiha","L'ultimo versetto del Corano","Il versetto della luce"],b:0,e:"Ubayy ibn Kaʿb lo disse al Profeta ﷺ, che approvò.",s:['h:kursi']},
  {q:"In quale sura si trova Âyat al-Kursî?",c:["Al-Baqara, versetto 255","Al-Fâtiha, versetto 1","Yâ-Sîn, versetto 1","Al-Ikhlâs, versetto 2"],b:0,e:"Il versetto del Trono è il 255° versetto della sura Al-Baqara.",s:['q:2:255']},
  {q:"Secondo Âyat al-Kursî, Allah è colto dalla sonnolenza o dal sonno?",c:["No, né sonnolenza né sonno Lo colgono","Sì, di notte","Sì, a volte","Solo dal sonno"],b:0,e:"Allah è il Vivente, Colui che sussiste da Sé.",s:['q:2:255']},
  {q:"Che cosa significa «Allâhu ṣ-ṣamad» nella sura Al-Ikhlâs?",c:["Allah è Colui di cui tutti hanno bisogno, e che non ha bisogno di nessuno","Allah è il Creatore del cielo","Allah è il Perdonatore","Allah è il Giudice"],b:0,e:"Aṣ-Ṣamad è uno dei nomi di Allah.",s:['q:112:2']},
  {q:"Che cosa significa il nome della sura «Al-Ikhlâs»?",c:["Il monoteismo puro, la sincerità","L'alba","La vittoria","Gli uomini"],b:0,e:"Purifica la fede da ogni associazione.",s:['f:ikhlas']},
  {q:"Secondo Âyat al-Kursî, che cosa concede Allah alle Sue creature della Sua scienza?",c:["Solo ciò che Egli vuole","Tutta la Sua scienza","Niente di niente","La metà"],b:0,e:"«E della Sua scienza, essi non abbracciano se non ciò che Egli vuole.»",s:['q:2:255']}
 ]},

/* ===================== PROFETI ===================== */
'pr-adam':{titre:"Adamo e Nûh",
 texte:["Adamo è il primo uomo e il primo profeta. Allah gli insegnò il nome di ogni cosa, poi ordinò agli angeli di prosternarsi davanti a lui. Iblîs rifiutò per orgoglio.",
  "Nûh (Noè) chiamò il suo popolo ad adorare Allah solo per 950 anni. Poche persone lo seguirono, nemmeno suo figlio.",
  "Per ordine di Allah, Nûh costruì l'arca, che lo salvò dal diluvio insieme ai credenti e a coppie di animali."],
 retenir:"Adamo, il primo uomo. Nûh, 950 anni di predicazione, e l'arca.",
 sources:['q:2:31','q:2:34','q:29:14'],
 quiz:[
  {q:"Chi è il primo profeta dell'umanità?",c:["Adamo","Nûh (Noè)","Ibrahim (Abramo)","Mûsâ (Mosè)"],b:0,e:"Adamo è il primo uomo e il primo profeta.",s:['q:2:31']},
  {q:"Che cosa ha insegnato Allah ad Adamo?",c:["Il nome di ogni cosa","Il Corano a memoria","Solo la lingua degli angeli","Solo i nomi dei profeti"],b:0,e:"«E insegnò ad Adamo tutti i nomi.»",s:['q:2:31']},
  {q:"Chi ha rifiutato di prosternarsi davanti ad Adamo?",c:["Iblîs","Jibrîl","Mikâ'îl","Tutti gli angeli"],b:0,e:"Gli angeli si prosternarono, tranne Iblîs.",s:['q:2:34']},
  {q:"Perché Iblîs ha rifiutato di prosternarsi davanti ad Adamo?",c:["Per orgoglio","Per dimenticanza","Per paura","Perché non aveva sentito l'ordine"],b:0,e:"Rifiutò, si gonfiò d'orgoglio e fu tra i miscredenti.",s:['q:2:34']},
  {q:"Dove vivevano Adamo e sua moglie prima di scendere sulla terra?",c:["In Paradiso","Alla Mecca","In Egitto","A Gerusalemme"],b:0,e:"«Abita il Paradiso, tu e tua moglie.»",s:['q:2:35']},
  {q:"Quale profeta ha costruito l'arca per ordine di Allah?",c:["Nûh (Noè)","Yûnus (Giona)","Sulaymân (Salomone)","ʿÎsâ (Gesù)"],b:0,e:"Nûh ha costruito l'arca sotto gli occhi di Allah e secondo la Sua rivelazione.",s:['q:11:37']},
  {q:"Secondo il Corano, per quanto tempo Nûh è rimasto tra il suo popolo?",c:["950 anni","40 anni","100 anni","313 anni"],b:0,e:"«Mille anni meno cinquanta.»",s:['q:29:14']},
  {q:"Chi fu salvato nell'arca di Nûh?",c:["Nûh, i credenti e coppie di animali","Tutto il suo popolo","Solo gli animali","Nessuno"],b:0,e:"Allah ordinò di farvi salire una coppia di ogni specie, la sua famiglia e i credenti.",s:['q:11:40']},
  {q:"Il figlio di Nûh è salito sull'arca?",c:["No, ha rifiutato ed è stato inghiottito","Sì, per primo","Sì, alla fine","Non aveva figli"],b:0,e:"Pensò di rifugiarsi su una montagna, ma le onde lo travolsero.",s:['q:11:43']},
  {q:"Come si chiama la moglie di Adamo, secondo la tradizione musulmana?",c:["Hawwâ' (Eva)","Maryam","Âsiya","Hâjar"],b:0,e:"Il Corano la menziona senza nominarla; il suo nome viene dalla Sunna.",s:['f:hawwa']}
 ]},
'pr-ibrahim':{titre:"Ibrahim, l'amico di Allah",
 texte:["Ibrahim (Abramo) rifiutò di adorare gli idoli del suo popolo. Fu gettato in un grande fuoco, ma Allah ordinò al fuoco di essere frescura e pace per lui.",
  "Allah lo ha preso come amico intimo (khalîl). È il padre di due profeti: Ismaʿîl e Isḥâq.",
  "Con suo figlio Ismaʿîl, innalzò le fondamenta della Kaaba. Il sacrificio dell'Eid al-Adha ricorda la sua obbedienza ad Allah."],
 retenir:"Ibrahim, l'amico di Allah, salvato dal fuoco, costruttore della Kaaba con Ismaʿîl.",
 sources:['q:21:69','q:4:125','q:2:127'],
 quiz:[
  {q:"Quale profeta ha innalzato le fondamenta della Kaaba con suo figlio Ismaʿîl?",c:["Ibrahim (Abramo)","Mûsâ (Mosè)","Dâwûd (Davide)","Adamo"],b:0,e:"Ibrahim e suo figlio Ismaʿîl hanno innalzato le fondamenta della Kaaba.",s:['q:2:127']},
  {q:"Che cosa accadde a Ibrahim quando il suo popolo lo gettò nel fuoco?",c:["Allah rese il fuoco fresco e innocuo per lui","Fuggì","Fu ferito","Fu salvato dalla pioggia"],b:0,e:"«O fuoco, sii frescura e salvezza per Abramo.»",s:['q:21:69']},
  {q:"Quale titolo dà il Corano al profeta Ibrahim?",c:["L'amico intimo di Allah (Khalîl)","Il sigillo dei profeti","Colui al quale Allah ha parlato","Lo Spirito di Allah"],b:0,e:"«E Allah aveva preso Abramo come amico prediletto.»",s:['q:4:125']},
  {q:"Quali sono i due figli profeti di Ibrahim?",c:["Ismaʿîl e Isḥâq","Mûsâ e Hârûn","Dâwûd e Sulaymân","Yaḥyâ e ʿÎsâ"],b:0,e:"Ibrahim ringraziò Allah per avergli dato Ismaʿîl e Isḥâq nella sua vecchiaia.",s:['q:14:39']},
  {q:"Che cosa faceva il popolo di Ibrahim, che lui rifiutava?",c:["Adorare delle statue","Digiunare","Fare l'elemosina","Fare il pellegrinaggio"],b:0,e:"Chiese loro: «Che cosa sono queste statue a cui siete così attaccati?»",s:['q:21:52']},
  {q:"Con che cosa Allah riscattò il figlio di Ibrahim al momento del sacrificio?",c:["Con un sacrificio generoso (un animale da sacrificare)","Con un'elemosina d'oro","Con il digiuno di suo padre","Con una preghiera notturna"],b:0,e:"La tradizione precisa che si trattava di un montone.",s:['q:37:107']},
  {q:"Quale festa ricorda l'obbedienza di Ibrahim ad Allah?",c:["L'Eid al-Adha","L'Eid al-Fitr","Il 1° di Muharram","Il Mawlid"],b:0,e:"Il sacrificio dell'Eid al-Adha commemora la sua prova.",s:['q:37:107']},
  {q:"Secondo il Corano, come è descritto Ibrahim?",c:["Un credente monoteista (ḥanîf), né ebreo né cristiano","Un re di Babilonia","Un angelo","Un poeta"],b:0,e:"Era interamente sottomesso ad Allah.",s:['q:3:67']},
  {q:"Quale figlio ha aiutato Ibrahim a innalzare le fondamenta della Kaaba?",c:["Ismaʿîl","Isḥâq","Yaʿqûb","Yûsuf"],b:0,e:"Ibrahim e Ismaʿîl innalzavano insieme le fondamenta della Casa.",s:['q:2:127']},
  {q:"Secondo il Corano, qual è la prima Casa di culto fondata per gli uomini?",c:["Quella di Bakka (la Mecca)","Quella di Gerusalemme","Quella di Medina","Quella di Taif"],b:0,e:"Bakka è un nome della Mecca.",s:['q:3:96']}
 ]},
'pr-yunus':{titre:"Yûnus, Yûsuf e Sulaymân",
 texte:["Yûnus (Giona) fu inghiottito da un grosso pesce. Nelle tenebre invocò Allah, che lo salvò dall'angoscia.",
  "La storia di Yûsuf (Giuseppe), tradito dai suoi fratelli e poi diventato ministro in Egitto, occupa tutta la sura 12: «il più bel racconto».",
  "Sulaymân (Salomone), figlio di Dâwûd, ricevette un regno immenso e comprendeva il linguaggio degli uccelli e delle formiche."],
 retenir:"Yûnus e il pesce. Yûsuf, sura 12. Sulaymân e il linguaggio degli animali.",
 sources:['q:37:142','q:12:3','q:27:18'],
 quiz:[
  {q:"Quale profeta è stato inghiottito da un grosso pesce?",c:["Yûnus (Giona)","Yûsuf (Giuseppe)","Ayyûb (Giobbe)","Lût (Lot)"],b:0,e:"Yûnus fu inghiottito dal pesce, poi Allah lo salvò.",s:['q:37:142']},
  {q:"Quale sura del Corano racconta per intero la storia del profeta Yûsuf (Giuseppe)?",c:["La sura 12, Yûsuf","La sura 1, Al-Fâtiha","La sura 36, Yâ-Sîn","La sura 112, Al-Ikhlâs"],b:0,e:"La sura 12 porta il suo nome.",s:['q:12:3']},
  {q:"Quale profeta comprendeva il linguaggio delle formiche?",c:["Sulaymân (Salomone)","Sâliḥ","Hûd","Zakariyyâ"],b:0,e:"Sulaymân sentì una formica avvertire le altre, e sorrise delle sue parole.",s:['q:27:18']},
  {q:"Quale invocazione ha pronunciato Yûnus nel ventre del pesce?",c:["«Lâ ilâha illâ anta, subḥânaka, innî kuntu mina ẓ-ẓâlimîn»","«Bismi Llâh»","«Allâhu akbar»","«Rabbanâ âtinâ»"],b:0,e:"«Non c'è divinità all'infuori di Te! Gloria a Te! Sono stato davvero tra gli ingiusti.»",s:['q:21:87']},
  {q:"Come ha risposto Allah all'invocazione di Yûnus?",c:["Lo salvò dall'angoscia","Lo lasciò nel pesce","Lo lasciò tre anni nel pesce","Non rispose"],b:0,e:"«Lo esaudimmo e lo salvammo dall'angoscia.»",s:['q:21:88']},
  {q:"Nel suo sogno da bambino, quante stelle Yûsuf ha visto prosternarsi davanti a lui?",c:["Undici, con il sole e la luna","Sette","Dodici","Una sola"],b:0,e:"Undici stelle, il sole e la luna.",s:['q:12:4']},
  {q:"Chi ha gettato Yûsuf in fondo a un pozzo?",c:["I suoi fratelli","Il Faraone","Dei mercanti","Suo padre"],b:0,e:"I suoi fratelli, gelosi, decisero di gettarlo in fondo al pozzo.",s:['q:12:15']},
  {q:"Come chiama il Corano la storia di Yûsuf?",c:["Il più bel racconto","Il racconto del fuoco","Il libro della saggezza","Il racconto dell'arca"],b:0,e:"«Noi ti raccontiamo il più bel racconto.»",s:['q:12:3']},
  {q:"Quale profeta ha ricevuto la conoscenza del linguaggio degli uccelli?",c:["Sulaymân","Yûnus","Nûh","Hûd"],b:0,e:"«Ci è stato insegnato il linguaggio degli uccelli», disse Sulaymân.",s:['q:27:16']},
  {q:"Chi era il padre di Sulaymân, anch'egli profeta e re?",c:["Dâwûd (Davide)","Ibrahim","Yaʿqûb","Mûsâ"],b:0,e:"«E Sulaymân ereditò da Dâwûd.»",s:['q:27:16']}
 ]},
'pr-musa':{titre:"Mûsâ, colui al quale Allah ha parlato",
 texte:["Mûsâ (Mosè) nacque in Egitto, all'epoca in cui il Faraone perseguitava i Banû Isrâ'îl. Su ispirazione di Allah, sua madre lo affidò al fiume, e la famiglia del Faraone lo raccolse.",
  "Allah gli parlò direttamente e lo inviò dal Faraone con suo fratello Hârûn, e con dei miracoli, come il suo bastone che diventò un serpente.",
  "Allah divise il mare per salvare Mûsâ e il suo popolo, e il Faraone fu inghiottito. Mûsâ è il profeta citato più spesso nel Corano."],
 retenir:"Mûsâ, salvato dalle acque, Kalîm Allâh, il mare diviso.",
 sources:['q:28:7','q:4:164','q:26:63'],
 quiz:[
  {q:"In quale paese è nato il profeta Mûsâ (Mosè)?",c:["In Egitto","In Arabia","In Iraq","In Yemen"],b:0,e:"Nacque in Egitto, sotto il regno del Faraone.",s:['q:28:7']},
  {q:"Che cosa fece la madre di Mûsâ per proteggerlo dal Faraone?",c:["Lo affidò al fiume","Lo nascose in una grotta","Partì nel deserto","Lo affidò a un pastore"],b:0,e:"Allah le ispirò di gettarlo nel fiume, senza timore.",s:['q:28:7']},
  {q:"Chi ha raccolto Mûsâ neonato dal fiume?",c:["La famiglia del Faraone","Dei pescatori","Ibrahim","Un re dello Yemen"],b:0,e:"La gente del Faraone lo raccolse.",s:['q:28:8']},
  {q:"Quale profeta è chiamato «Kalîm Allâh», colui al quale Allah ha parlato direttamente?",c:["Mûsâ","Ibrahim","ʿÎsâ","Nûh"],b:0,e:"«E Allah parlò a Mosè direttamente.»",s:['q:4:164']},
  {q:"Che cosa diventò il bastone di Mûsâ quando lo gettò a terra?",c:["Un serpente","Un albero","Una colomba","Una spada"],b:0,e:"«Lo gettò: ed ecco un serpente che strisciava.»",s:['q:20:20']},
  {q:"Che cosa accadde quando Mûsâ colpì il mare con il suo bastone?",c:["Si divise in due","Si trasformò in sabbia","Si prosciugò di colpo","Niente"],b:0,e:"Ogni parte era come un'enorme montagna.",s:['q:26:63']},
  {q:"Che cosa accadde al Faraone e al suo esercito che inseguivano Mûsâ?",c:["Furono inghiottiti dal mare","Si convertirono","Tornarono in Egitto","Attraversarono anche loro"],b:0,e:"Allah salvò Mûsâ e quelli che erano con lui, e fece annegare gli altri.",s:['q:26:66']},
  {q:"Come si chiamava il fratello di Mûsâ, che lo aiutò nella sua missione?",c:["Hârûn (Aronne)","Yûsuf","Isḥâq","Yaḥyâ"],b:0,e:"Mûsâ chiese ad Allah di dargli suo fratello Hârûn come aiutante.",s:['q:20:30']},
  {q:"Verso quale re Allah inviò Mûsâ?",c:["Il Faraone","Nimrod","Il re di Saba","Golia"],b:0,e:"«Va' dal Faraone, perché ha oltrepassato ogni limite.»",s:['q:20:24']},
  {q:"Quale profeta è citato più spesso per nome nel Corano?",c:["Mûsâ","Muhammad ﷺ","Ibrahim","Nûh"],b:0,e:"Mûsâ è nominato più di 130 volte nel Corano.",s:['f:musa']}
 ]},
'pr-isa':{titre:"ʿÎsâ e Maryam",
 texte:["Maryam (Maria), madre di ʿÎsâ, è l'unica donna nominata nel Corano. Allah l'ha scelta al di sopra delle donne dei mondi, e una sura porta il suo nome.",
  "ʿÎsâ (Gesù) è nato senza padre, per volontà di Allah, come Adamo fu creato senza padre né madre. Da neonato, parlò nella culla.",
  "Per i musulmani, ʿÎsâ è un grande profeta e messaggero di Allah, il Messia, al quale fu rivelato l'Injîl (Vangelo)."],
 retenir:"Maryam, scelta tra le donne. ʿÎsâ, nato senza padre, profeta e Messia.",
 sources:['q:3:42','q:3:59','q:19:30'],
 quiz:[
  {q:"Qual è l'unica donna nominata nel Corano?",c:["Maryam","Khadîja","Âsiya","Hawwâ'"],b:0,e:"Maryam è l'unica donna citata per nome; la sura 19 porta il suo nome.",s:['f:maryam']},
  {q:"Che cosa dice il Corano di Maryam?",c:["Allah l'ha scelta al di sopra delle donne dei mondi","Era regina d'Egitto","Era profetessa di Medina","Il Corano non ne parla"],b:0,e:"Gli angeli le annunciarono che Allah l'aveva eletta e purificata.",s:['q:3:42']},
  {q:"Come è nato il profeta ʿÎsâ (Gesù)?",c:["Senza padre, per volontà di Allah","Come tutti","Nel palazzo del Faraone","Alla Mecca"],b:0,e:"Allah dice «Sii», ed egli fu.",s:['q:3:59']},
  {q:"A quale creazione il Corano paragona quella di ʿÎsâ?",c:["A quella di Adamo","A quella degli angeli","A quella di Nûh","A quella di Iblîs"],b:0,e:"Adamo fu creato senza padre né madre; ʿÎsâ senza padre.",s:['q:3:59']},
  {q:"Quale miracolo fece ʿÎsâ quando era neonato?",c:["Parlò nella culla","Camminò sull'acqua","Fece sgorgare l'acqua di Zamzam","Attraversò il mare"],b:0,e:"Difese sua madre parlando dalla culla.",s:['q:19:30']},
  {q:"Quali furono le prime parole di ʿÎsâ neonato, secondo il Corano?",c:["«Sono il servo di Allah»","«Sono re»","«Sono un angelo»","«Sono il figlio di Zakariyyâ»"],b:0,e:"«In verità sono il servo di Allah. Mi ha dato il Libro e mi ha fatto profeta.»",s:['q:19:30']},
  {q:"Quale titolo dà il Corano a ʿÎsâ?",c:["Al-Masîḥ, il Messia","Il Khalîl","Il sigillo dei profeti","Kalîm Allâh"],b:0,e:"Gli angeli annunciano a Maryam: «il suo nome sarà Al-Masîḥ, ʿÎsâ, figlio di Maria».",s:['q:3:45']},
  {q:"Quale libro Allah ha rivelato al profeta ʿÎsâ?",c:["L'Injîl (Vangelo)","La Tawrât (Torah)","Lo Zabûr (Salmi)","Il Corano"],b:0,e:"«Gli abbiamo dato il Vangelo, in cui c'è guida e luce.»",s:['q:5:46']},
  {q:"Per i musulmani, chi è ʿÎsâ?",c:["Un profeta e messaggero di Allah","Una divinità","Un angelo","Un re di Gerusalemme"],b:0,e:"Egli stesso si presenta come servo di Allah e profeta.",s:['q:19:30']},
  {q:"Chi fu inviato a Maryam per annunciarle la nascita di ʿÎsâ?",c:["Lo Spirito di Allah, l'angelo Jibrîl","Zakariyyâ","Yaḥyâ","L'angelo Mikâ'îl"],b:0,e:"I sapienti spiegano che «il Nostro Spirito» indica l'angelo Jibrîl.",s:['q:19:19']}
 ]},
'pr-muhammad':{titre:"Muhammad ﷺ, l'ultimo profeta",
 texte:["Muhammad ﷺ è nato alla Mecca verso il 570, l'«anno dell'Elefante», nella tribù dei Quraysh. Orfano di padre prima della nascita, perse la madre Âmina a 6 anni e fu cresciuto dal nonno, poi dallo zio Abû Ṭâlib.",
  "Noto per la sua onestà, lo chiamavano al-Amîn, «il degno di fiducia». Ricevette la prima rivelazione a 40 anni.",
  "Morì a Medina nel 632, all'età di 63 anni. Allah lo ha inviato come misericordia per i mondi."],
 retenir:"Nato alla Mecca verso il 570, rivelazione a 40 anni, morto a Medina a 63 anni.",
 sources:['q:21:107','q:68:4','h:vie'],
 quiz:[
  {q:"In quale città è nato il Profeta Muhammad ﷺ?",c:["La Mecca","Medina","Gerusalemme","Taif"],b:0,e:"È nato alla Mecca verso il 570.",s:['f:sira']},
  {q:"Come si chiama l'anno di nascita del Profeta ﷺ?",c:["L'anno dell'Elefante","L'anno dell'Egira","L'anno della tristezza","L'anno della vittoria"],b:0,e:"L'anno in cui un esercito venuto con degli elefanti attaccò la Mecca (sura 105).",s:['q:105:1']},
  {q:"Come si chiamava la madre del Profeta ﷺ?",c:["Âmina","Khadîja","Ḥalîma","Fâṭima"],b:0,e:"Âmina bint Wahb morì quando lui aveva 6 anni.",s:['f:sira']},
  {q:"Quale zio ha cresciuto e protetto il Profeta ﷺ?",c:["Abû Ṭâlib","Abû Lahab","Ḥamza","Al-ʿAbbâs"],b:0,e:"Dopo la morte del nonno, lo zio Abû Ṭâlib si prese cura di lui.",s:['f:sira']},
  {q:"Quale soprannome davano i Meccani al Profeta ﷺ prima della rivelazione?",c:["Al-Amîn, il degno di fiducia","Al-Fârûq","Aṣ-Ṣiddîq","Sayf Allâh"],b:0,e:"Era noto a tutti per la sua onestà.",s:['f:sira']},
  {q:"A che età è morto il Profeta ﷺ?",c:["63 anni","40 anni","70 anni","53 anni"],b:0,e:"Ibn ʿAbbâs riferisce che è morto a 63 anni.",s:['h:vie']},
  {q:"In quale città è morto il Profeta ﷺ?",c:["Medina","La Mecca","Gerusalemme","Damasco"],b:0,e:"È morto a Medina nel 632 ed è sepolto lì.",s:['f:sira']},
  {q:"Secondo il Corano, perché Allah ha inviato Muhammad ﷺ?",c:["Come misericordia per i mondi","Per essere re","Per punire le persone","Solo per gli Arabi"],b:0,e:"«Non ti abbiamo inviato se non come misericordia per i mondi.»",s:['q:21:107']},
  {q:"Che cosa dice il Corano del carattere del Profeta ﷺ?",c:["È di una moralità eminente","È severo","È indifferente","Il Corano non ne parla"],b:0,e:"«E in verità tu sei di una moralità eminente.»",s:['q:68:4']},
  {q:"A quale tribù apparteneva il Profeta ﷺ?",c:["Quraysh","Aws","Khazraj","Thaqîf"],b:0,e:"Quraysh, la grande tribù della Mecca.",s:['f:sira']}
 ]},
'pr-livres':{titre:"I libri rivelati e la fede",
 texte:["Allah ha rivelato dei libri ad alcuni profeti: la Tawrât (Torah) a Mûsâ, lo Zabûr (Salmi) a Dâwûd, l'Injîl (Vangelo) a ʿÎsâ, e il Corano a Muhammad ﷺ.",
  "Il Corano nomina 25 profeti, ma Allah ne ha inviati molti altri. Il credente crede in tutti, senza distinzione.",
  "La fede (îmân) si basa su sei pilastri: credere in Allah, nei Suoi angeli, nei Suoi libri, nei Suoi messaggeri, nell'Ultimo Giorno e nel destino."],
 retenir:"Tawrât, Zabûr, Injîl, Corano. Sei pilastri della fede.",
 sources:['q:5:44','q:2:285','h:jibril'],
 quiz:[
  {q:"Quale libro Allah ha rivelato al profeta Mûsâ (Mosè)?",c:["La Tawrât (Torah)","Lo Zabûr (Salmi)","L'Injîl (Vangelo)","Il Corano"],b:0,e:"La Tawrât a Mûsâ, lo Zabûr a Dâwûd, l'Injîl a ʿÎsâ, il Corano a Muhammad ﷺ.",s:['q:5:44']},
  {q:"Quanti profeti sono citati per nome nel Corano?",c:["25","12","40","313"],b:0,e:"25 profeti sono nominati; 18 di loro sono citati insieme nella sura Al-Anʿâm.",s:['f:prophetes25']},
  {q:"Quale profeta il Corano chiama «il sigillo dei profeti», cioè l'ultimo?",c:["Muhammad ﷺ","ʿÎsâ (Gesù)","Mûsâ (Mosè)","Ibrahim (Abramo)"],b:0,e:"Muhammad ﷺ è l'ultimo dei profeti.",s:['q:33:40']},
  {q:"Quale libro è stato rivelato al profeta Dâwûd (Davide)?",c:["Lo Zabûr (Salmi)","La Tawrât","L'Injîl","I fogli di Ibrahim"],b:0,e:"«E abbiamo dato lo Zabûr a Davide.»",s:['q:4:163']},
  {q:"Credere nei libri rivelati fa parte della fede del musulmano?",c:["Sì, è un pilastro della fede","No, solo nel Corano","No, è facoltativo","Solo durante il Ramadan"],b:0,e:"I credenti credono in Allah, nei Suoi angeli, nei Suoi libri e nei Suoi messaggeri.",s:['q:2:285']},
  {q:"Quanti pilastri conta la fede (îmân)?",c:["6","5","4","10"],b:0,e:"Allah, gli angeli, i libri, i messaggeri, l'Ultimo Giorno e il destino.",s:['h:jibril']},
  {q:"Quale di questi elementi NON è un pilastro della fede (îmân)?",c:["Il digiuno del Ramadan","La fede negli angeli","La fede nell'Ultimo Giorno","La fede nei libri"],b:0,e:"Il digiuno è un pilastro dell'islam (la pratica), non della fede (il credo).",s:['h:jibril']},
  {q:"Quale libro Allah si è impegnato a preservare?",c:["Il Corano","La Tawrât","Lo Zabûr","Tutti i libri dei re"],b:0,e:"«Siamo Noi che ne siamo i custodi.»",s:['q:15:9']},
  {q:"Il Corano racconta la storia di tutti i messaggeri inviati da Allah?",c:["No, solo di alcuni","Sì, di tutti","Non ne racconta nessuno","Solo degli Arabi"],b:0,e:"«Ci sono messaggeri di cui ti abbiamo raccontato la storia, e altri di cui non ti abbiamo raccontato la storia.»",s:['q:4:164']},
  {q:"Secondo il Corano, i credenti fanno distinzione tra i messaggeri nella loro fede?",c:["No, credono in tutti","Sì, credono in uno solo","Sì, rifiutano quelli antichi","Non credono in nessuno"],b:0,e:"«Non facciamo alcuna distinzione tra i Suoi messaggeri.»",s:['q:2:285']}
 ]},

/* ===================== STORIA E COMPAGNI ===================== */
'h-khadija':{titre:"Khadîja e gli inizi dell'islam",
 texte:["Khadîja era una commerciante rispettata della Mecca. Sposò il Profeta ﷺ, che allora aveva 25 anni.",
  "Dopo la prima rivelazione, fu lei a confortarlo e a credere in lui per prima. Lo portò dal suo cugino Waraqa ibn Nawfal.",
  "Tra i primi musulmani ci sono Abû Bakr, ʿAlî, Zayd ibn Ḥâritha e Bilâl. Per 13 anni, alla Mecca, i musulmani furono perseguitati; Sumayya fu la prima martire."],
 retenir:"Khadîja, la prima a credere. 13 anni di predicazione alla Mecca.",
 sources:['h:hira','f:debuts'],
 quiz:[
  {q:"Chi fu la prima moglie del Profeta ﷺ?",c:["Khadîja","ʿÂ'isha","Ḥafṣa","Zaynab"],b:0,e:"Khadîja fu la prima persona a credere nel suo messaggio.",s:['h:hira']},
  {q:"Chi confortò il Profeta ﷺ subito dopo la prima rivelazione nella grotta di Hira?",c:["Khadîja","Abû Bakr","ʿAlî","Bilâl"],b:0,e:"Tornò da Khadîja, che lo rassicurò.",s:['h:hira']},
  {q:"Quale attività svolgeva Khadîja alla Mecca?",c:["Il commercio","La medicina","La poesia","L'allevamento di cammelli"],b:0,e:"Era una ricca commerciante rispettata.",s:['f:debuts']},
  {q:"Quanti anni aveva il Profeta ﷺ quando sposò Khadîja?",c:["25 anni","40 anni","18 anni","30 anni"],b:0,e:"Aveva 25 anni.",s:['f:debuts']},
  {q:"Da chi Khadîja portò il Profeta ﷺ dopo la prima rivelazione?",c:["Dal suo cugino Waraqa ibn Nawfal","Da Abû Ṭâlib","Da Abû Bakr","Dal re di Abissinia"],b:0,e:"Waraqa conosceva le Scritture antiche.",s:['h:hira']},
  {q:"Quale ragazzo fu tra i primi ad abbracciare l'islam?",c:["ʿAlî ibn Abî Ṭâlib","ʿUmar","Khâlid","Muʿâwiya"],b:0,e:"ʿAlî, cugino del Profeta ﷺ, era ancora un bambino.",s:['f:debuts']},
  {q:"Per circa quanti anni il Profeta ﷺ predicò alla Mecca prima dell'Egira?",c:["13 anni","3 anni","23 anni","40 anni"],b:0,e:"Ibn ʿAbbâs riferisce che restò 13 anni alla Mecca dopo la rivelazione.",s:['h:vie']},
  {q:"Quale amico del Profeta ﷺ fu il primo uomo adulto ad abbracciare l'islam?",c:["Abû Bakr","ʿUmar","ʿUthmân","Ḥamza"],b:0,e:"Abû Bakr credette in lui senza esitare.",s:['f:debuts']},
  {q:"Quale ex schiavo, perseguitato per la sua fede, diventò il primo muezzin dell'islam?",c:["Bilâl ibn Rabâḥ","Zayd ibn Ḥâritha","Salmân","Anas"],b:0,e:"La sua voce arrivava lontano: il Profeta ﷺ gli affidò l'adhân.",s:['h:adhan']},
  {q:"Come si chiamava la prima martire dell'islam?",c:["Sumayya","Khadîja","Fâṭima","Asmâ'"],b:0,e:"Sumayya, madre di ʿAmmâr, fu uccisa per la sua fede alla Mecca.",s:['f:debuts']}
 ]},
'h-hegire':{titre:"L'Egira",
 texte:["Nel 622, di fronte alle persecuzioni, il Profeta ﷺ lasciò la Mecca per Medina, allora chiamata Yathrib: è l'Egira. Segna l'anno 1 del calendario musulmano.",
  "Durante il viaggio, si nascose nella grotta di Thawr con il suo amico Abû Bakr.",
  "A Medina fu accolto dagli Anṣâr (gli «Ausiliari»), che condivisero i loro beni con i Muhâjirûn (gli «Emigrati»). Lì costruì la sua moschea."],
 retenir:"622: l'Egira, anno 1. Muhâjirûn e Anṣâr.",
 sources:['q:9:40','f:hegire'],
 quiz:[
  {q:"Che cos'è l'Egira?",c:["La migrazione del Profeta ﷺ dalla Mecca a Medina","Il primo pellegrinaggio","Una battaglia","La nascita del Profeta ﷺ"],b:0,e:"Segna l'anno 1 del calendario musulmano.",s:['f:hegire']},
  {q:"Quale Compagno accompagnava il Profeta ﷺ nella grotta durante l'Egira?",c:["Abû Bakr as-Siddîq","ʿUmar ibn al-Khaṭṭâb","ʿAlî ibn Abî Ṭâlib","Bilâl"],b:0,e:"Abû Bakr era «il secondo dei due» nella grotta.",s:['q:9:40']},
  {q:"In quale anno è avvenuta l'Egira?",c:["622","570","632","610"],b:0,e:"L'Egira è avvenuta nel 622 dell'era cristiana.",s:['f:hegire']},
  {q:"In quale grotta si è nascosto il Profeta ﷺ durante l'Egira?",c:["La grotta di Thawr","La grotta di Hira","La grotta di Uhud","La grotta di Badr"],b:0,e:"Thawr è a sud della Mecca; Hira, luogo della prima rivelazione, a nord.",s:['f:hegire']},
  {q:"Qual era l'antico nome di Medina?",c:["Yathrib","Bakka","Taif","Qubâ'"],b:0,e:"Il Corano cita questo nome: «O gente di Yathrib».",s:['q:33:13']},
  {q:"Come si chiamano gli abitanti di Medina che accolsero i musulmani?",c:["Gli Anṣâr","I Muhâjirûn","I Quraysh","I Banû Isrâ'îl"],b:0,e:"Anṣâr significa «gli Ausiliari».",s:['q:9:100']},
  {q:"Come si chiamano i musulmani che emigrarono dalla Mecca a Medina?",c:["I Muhâjirûn","Gli Anṣâr","I Khawârij","I Beduini"],b:0,e:"Muhâjirûn significa «gli Emigrati».",s:['q:9:100']},
  {q:"Che cosa disse il Profeta ﷺ ad Abû Bakr nella grotta, secondo il Corano?",c:["«Non rattristarti, Allah è con noi»","«Fuggiamo in fretta»","«Torniamo alla Mecca»","«Combattiamoli»"],b:0,e:"È il versetto 40 della sura At-Tawba.",s:['q:9:40']},
  {q:"Sotto quale califfo fu adottato il calendario dell'Egira?",c:["ʿUmar","Abû Bakr","ʿUthmân","ʿAlî"],b:0,e:"ʿUmar fece dell'Egira il punto di partenza del calendario.",s:['f:hegire']},
  {q:"Che cosa ha costruito il Profeta ﷺ arrivando a Medina?",c:["La sua moschea","Un palazzo","Una fortezza","Un mercato"],b:0,e:"La Moschea del Profeta (al-Masjid an-Nabawî).",s:['f:hegire']}
 ]},
'h-badr':{titre:"La battaglia di Badr",
 texte:["Il 17 di Ramadan dell'anno 2 dell'Egira (624), i musulmani affrontarono l'esercito dei Quraysh vicino ai pozzi di Badr.",
  "Erano circa 313, contro quasi 1000 combattenti. Allah li sostenne con degli angeli, e ottennero la vittoria.",
  "Il Corano chiama questo giorno «il giorno del Discernimento» (yawm al-furqân), quello in cui la verità fu distinta dall'errore."],
 retenir:"17 Ramadan anno 2: Badr, 313 contro 1000, il giorno del Discernimento.",
 sources:['q:3:123','q:8:9','q:8:41'],
 quiz:[
  {q:"In quale mese si è svolta la battaglia di Badr?",c:["Ramadan","Muharram","Dhul-Hijja","Rajab"],b:0,e:"Il 17 di Ramadan dell'anno 2 dell'Egira.",s:['f:badr']},
  {q:"In quale anno dell'Egira si è svolta la battaglia di Badr?",c:["L'anno 2","L'anno 8","L'anno 10","L'anno 1"],b:0,e:"Nel 624 dell'era cristiana.",s:['f:badr']},
  {q:"Circa quanti musulmani hanno combattuto a Badr?",c:["Circa 313","Circa 3000","Circa 10 000","Circa 50"],b:0,e:"Erano circa 313.",s:['f:badr']},
  {q:"Circa quanti combattenti contava l'esercito dei Quraysh a Badr?",c:["Quasi 1000","Quasi 100","Quasi 10 000","Quasi 300"],b:0,e:"I Meccani erano tre volte più numerosi.",s:['f:badr']},
  {q:"Secondo il Corano, come ha sostenuto Allah i musulmani a Badr?",c:["Con degli angeli","Con una tempesta di sabbia","Con rinforzi dalla Persia","Solo con la pioggia"],b:0,e:"Allah rispose al loro appello inviando degli angeli.",s:['q:8:9']},
  {q:"Secondo la sura Al-Anfâl, quanti angeli Allah promise di inviare come rinforzo a Badr?",c:["Mille","Cento","Dieci","Trecento"],b:0,e:"«Vi aiuterò con mille angeli che si susseguono gli uni agli altri.»",s:['q:8:9']},
  {q:"Come chiama il Corano il giorno di Badr?",c:["Il giorno del Discernimento (yawm al-furqân)","Il giorno della Resurrezione","Il giorno dell'Eid","Il giorno dell'Egira"],b:0,e:"Il giorno in cui la verità fu distinta dall'errore.",s:['q:8:41']},
  {q:"Contro quale tribù combatterono i musulmani a Badr?",c:["Quraysh","I Romani","I Persiani","Gli Anṣâr"],b:0,e:"L'esercito dei Quraysh veniva dalla Mecca.",s:['f:badr']},
  {q:"In quale giorno del Ramadan si è svolta la battaglia di Badr?",c:["Il 17","Il 27","Il 1°","Il 10"],b:0,e:"Il 17 di Ramadan dell'anno 2.",s:['f:badr']},
  {q:"Secondo il Corano, in quale situazione si trovavano i musulmani a Badr?",c:["Erano deboli e umiliati","Erano molto numerosi","Erano ricchi","Erano a cavallo"],b:0,e:"«Allah vi ha dato la vittoria a Badr, quando eravate umiliati.»",s:['q:3:123']}
 ]},
'h-fath':{titre:"La conquista della Mecca",
 texte:["Nell'anno 8 dell'Egira (630), durante il mese di Ramadan, il Profeta ﷺ entrò alla Mecca con circa 10 000 musulmani, quasi senza combattere.",
  "Perdonò i suoi antichi nemici e purificò la Kaaba dai suoi 360 idoli, recitando: «La verità è venuta e la falsità è svanita.»",
  "La sura An-Naṣr annuncia questo soccorso di Allah e l'ingresso delle persone in massa nell'islam."],
 retenir:"Ramadan anno 8: la Mecca aperta, gli idoli distrutti, il perdono concesso.",
 sources:['q:17:81','h:idoles','q:110:1'],
 quiz:[
  {q:"In quale anno dell'Egira fu conquistata la Mecca?",c:["L'anno 8","L'anno 2","L'anno 1","L'anno 11"],b:0,e:"Nel 630 dell'era cristiana.",s:['f:fath']},
  {q:"In quale mese avvenne la conquista della Mecca?",c:["Ramadan","Shawwâl","Dhul-Hijja","Muharram"],b:0,e:"La conquista della Mecca avvenne in Ramadan.",s:['f:fath']},
  {q:"Circa quanti musulmani accompagnavano il Profeta ﷺ durante la conquista della Mecca?",c:["Circa 10 000","Circa 313","Circa 1000","Circa 100"],b:0,e:"Un esercito di circa 10 000 uomini.",s:['f:fath']},
  {q:"Quanti idoli circondavano la Kaaba il giorno della conquista della Mecca?",c:["360","12","99","1000"],b:0,e:"ʿAbdallah ibn Masʿûd riferisce che ce n'erano 360.",s:['h:idoles']},
  {q:"Quale versetto recitò il Profeta ﷺ abbattendo gli idoli della Kaaba?",c:["«La verità è venuta e la falsità è svanita»","«Nel nome di Allah»","«Di': Egli è Allah, l'Unico»","«Leggi!»"],b:0,e:"È il versetto 81 della sura Al-Isrâ'.",s:['q:17:81','h:idoles']},
  {q:"Come trattò il Profeta ﷺ i suoi antichi nemici meccani dopo la conquista?",c:["Li perdonò","Li cacciò","Li imprigionò","Li esiliò in Abissinia"],b:0,e:"Concesse un perdono generale ai Meccani.",s:['f:fath']},
  {q:"Quale sura annuncia «il soccorso di Allah e la vittoria»?",c:["An-Naṣr (110)","Al-Fatḥ (48)","Al-Fîl (105)","Al-Kawthar (108)"],b:0,e:"«Quando giungono il soccorso di Allah e la vittoria.»",s:['q:110:1']},
  {q:"Secondo la sura An-Naṣr, come sono entrate le persone nell'islam?",c:["In massa","Uno alla volta, in segreto","Con la forza","Non è entrato nessuno"],b:0,e:"«E vedrai le persone entrare in massa nella religione di Allah.»",s:['q:110:2']},
  {q:"La conquista della Mecca è avvenuta con una grande battaglia?",c:["No, quasi senza combattere","Sì, la più grande della storia","Sì, durata un anno","Sì, ai piedi del monte Uhud"],b:0,e:"La città fu aperta pacificamente, quasi senza scontri.",s:['f:fath']},
  {q:"Che cosa chiede la sura An-Naṣr dopo la vittoria?",c:["Glorificare Allah e chiederGli perdono","Fare subito il hajj","Digiunare tre giorni","Ricostruire la Kaaba"],b:0,e:"«Glorifica il tuo Signore lodandoLo e implora il Suo perdono.»",s:['q:110:3']}
 ]},
'h-califes':{titre:"I primi quattro califfi",
 texte:["Dopo la morte del Profeta ﷺ nel 632, si succedettero quattro califfi: Abû Bakr, ʿUmar, ʿUthmân e ʿAlî. Sono chiamati i «califfi ben guidati».",
  "Abû Bakr fece raccogliere il Corano in un'unica raccolta da Zayd ibn Thâbit. Sotto ʿUmar l'islam si estese e fu adottato il calendario dell'Egira.",
  "ʿUthmân fece copiare il Corano in diversi esemplari inviati nelle province. ʿAlî, cugino e genero del Profeta ﷺ, fu il quarto califfo."],
 retenir:"Abû Bakr, ʿUmar, ʿUthmân, ʿAlî: i quattro califfi ben guidati.",
 sources:['h:compilation','h:copies','f:califes'],
 quiz:[
  {q:"Chi fu il primo califfo dopo la morte del Profeta ﷺ?",c:["Abû Bakr","ʿUmar","ʿAlî","ʿUthmân"],b:0,e:"Abû Bakr, poi ʿUmar, ʿUthmân e ʿAlî.",s:['f:califes']},
  {q:"Quanti «califfi ben guidati» sono succeduti al Profeta ﷺ?",c:["4","3","5","12"],b:0,e:"Sono chiamati al-khulafâ' ar-râshidûn.",s:['f:califes']},
  {q:"Qual è l'ordine dei primi quattro califfi?",c:["Abû Bakr, ʿUmar, ʿUthmân, ʿAlî","ʿAlî, ʿUmar, Abû Bakr, ʿUthmân","ʿUmar, Abû Bakr, ʿAlî, ʿUthmân","ʿUthmân, ʿAlî, ʿUmar, Abû Bakr"],b:0,e:"Dal 632 al 661.",s:['f:califes']},
  {q:"Sotto quale califfo il Corano fu raccolto per la prima volta in un'unica raccolta?",c:["Abû Bakr","ʿUmar","ʿUthmân","ʿAlî"],b:0,e:"Dopo la battaglia della Yamâma, in cui furono uccisi molti recitatori.",s:['h:compilation']},
  {q:"Quale Compagno fu incaricato di raccogliere il Corano sotto Abû Bakr?",c:["Zayd ibn Thâbit","Bilâl","Khâlid ibn al-Walîd","Salmân"],b:0,e:"Zayd ibn Thâbit era stato scriba della rivelazione.",s:['h:compilation']},
  {q:"Quale califfo fece copiare il Corano in diversi esemplari inviati nelle province?",c:["ʿUthmân","Abû Bakr","ʿUmar","ʿAlî"],b:0,e:"Per unificare la recitazione in tutto il mondo musulmano.",s:['h:copies']},
  {q:"Quale legame di parentela univa ʿAlî al Profeta ﷺ?",c:["Suo cugino e genero","Suo fratello","Suo zio","Suo nonno"],b:0,e:"ʿAlî era il marito di Fâṭima, figlia del Profeta ﷺ.",s:['f:califes']},
  {q:"Quale califfo era soprannominato «al-Fârûq», colui che distingue il vero dal falso?",c:["ʿUmar","Abû Bakr","ʿUthmân","ʿAlî"],b:0,e:"ʿUmar ibn al-Khaṭṭâb.",s:['f:califes']},
  {q:"Quale califfo era soprannominato «aṣ-Ṣiddîq», il veridico?",c:["Abû Bakr","ʿUmar","ʿUthmân","ʿAlî"],b:0,e:"Abû Bakr credette immediatamente a tutto ciò che riferiva il Profeta ﷺ.",s:['f:califes']},
  {q:"Quale califfo sposò una dopo l'altra due figlie del Profeta ﷺ?",c:["ʿUthmân","ʿUmar","Abû Bakr","ʿAlî"],b:0,e:"Da qui il suo soprannome «Dhû n-Nûrayn», l'uomo dalle due luci.",s:['f:califes']}
 ]}
},

/* Riferimenti (fonti storiche o pratiche, senza testo arabo) */
faits:{
 mois:{titre:"Riferimento",texte:"I 12 mesi dell'Egira: Muharram, Safar, Rabîʿ al-awwal, Rabîʿ ath-thânî, Jumâdâ al-ûlâ, Jumâdâ al-âkhira, Rajab, Shaʿbân, Ramadan, Shawwâl, Dhul-Qaʿda, Dhul-Hijja."},
 jeune2:{titre:"Riferimento storico",texte:"Il digiuno del Ramadan è stato prescritto a Medina, nell'anno 2 dell'Egira (624)."},
 conditions:{titre:"Riferimento",texte:"I sapienti indicano come condizioni dell'obbligo del digiuno: essere musulmano, pubere, sano di mente e in grado di digiunare."},
 aid:{titre:"Riferimento",texte:"L'islam conta due feste: l'Eid al-Fitr, il 1° di Shawwâl, alla fine del Ramadan, e l'Eid al-Adha, il 10 di Dhul-Hijja, durante il hajj."},
 shahada:{titre:"Riferimento",texte:"Testo della shahada: «Ash-hadu an lâ ilâha illâ Llâh, wa ash-hadu anna Muḥammadan rasûlu Llâh» — «Attesto che non c'è divinità all'infuori di Allah, e attesto che Muhammad è il Messaggero di Allah»."},
 rakat:{titre:"Pratica tramandata",texte:"Il numero di unità di ogni preghiera viene dalla pratica del Profeta ﷺ, tramandata da tutti i musulmani: Fajr 2, Dhohr 4, ʿAsr 4, Maghrib 3, ʿIshâ' 4, cioè 17 rakʿât al giorno."},
 zakat:{titre:"Riferimento",texte:"La zakat sul denaro è del 2,5% (un quarantesimo) dei risparmi che raggiungono il niṣâb e restano in possesso per un anno lunare (il ḥawl). La sadaqa è un'elemosina volontaria. Per i casi particolari, bisogna chiedere a un sapiente."},
 hajj:{titre:"Riferimento",texte:"Il hajj si svolge dall'8 al 13 di Dhul-Hijja. Il pellegrino entra in iḥrâm (gli uomini indossano due pezzi di tessuto bianco non cuciti), fa il ṭawâf (sette giri della Kaaba) e il saʿy (sette percorsi tra Ṣafâ e Marwa). Il 9 è il giorno di ʿArafa, il 10 l'Eid al-Adha."},
 coran:{titre:"Riferimento",texte:"Il Corano conta 114 sure e 6236 versetti secondo il conteggio più diffuso. È diviso in 30 parti (juz'). Un versetto si dice âya. Le sure rivelate prima dell'Egira sono dette meccane, quelle successive medinesi. La più lunga è Al-Baqara (286 versetti)."},
 tawba:{titre:"Riferimento",texte:"La sura At-Tawba (9) è l'unica delle 114 sure a non iniziare con «Bismi Llâhi r-Raḥmâni r-Raḥîm»."},
 ikhlas:{titre:"Riferimento",texte:"Al-Ikhlâs significa «il monoteismo puro, la sincerità»: la sura purifica la fede da ogni associazione."},
 hawwa:{titre:"Riferimento",texte:"Il Corano menziona la moglie di Adamo senza nominarla. Il suo nome, Hawwâ' (Eva), viene dalla Sunna e dai sapienti."},
 musa:{titre:"Riferimento",texte:"Mûsâ è il profeta nominato più spesso nel Corano: più di 130 volte."},
 maryam:{titre:"Riferimento",texte:"Maryam è l'unica donna citata per nome nel Corano. La sura 19 porta il suo nome."},
 sira:{titre:"Riferimento storico",texte:"Il Profeta ﷺ è nato alla Mecca verso il 570, nella tribù dei Quraysh. Orfano di padre, perse la madre Âmina a 6 anni, fu cresciuto dal nonno ʿAbd al-Muṭṭalib e poi dallo zio Abû Ṭâlib. Lo chiamavano al-Amîn. Morì a Medina nel 632."},
 prophetes25:{titre:"Riferimento",texte:"Nel Corano sono nominati 25 profeti. 18 di loro sono citati insieme nella sura Al-Anʿâm (6), versetti da 83 a 86."},
 debuts:{titre:"Riferimento storico",texte:"Khadîja, ricca commerciante, sposò il Profeta ﷺ quando lui aveva 25 anni. Tra i primissimi musulmani: Khadîja, Abû Bakr, ʿAlî (ancora bambino), Zayd ibn Ḥâritha. Bilâl, schiavo perseguitato e poi affrancato, divenne il primo muezzin. Sumayya, madre di ʿAmmâr, fu la prima martire."},
 hegire:{titre:"Riferimento storico",texte:"L'Egira avvenne nel 622. Il Profeta ﷺ e Abû Bakr si nascosero nella grotta di Thawr. Medina si chiamava Yathrib. Il Profeta ﷺ vi costruì la sua moschea. Il calendario dell'Egira fu adottato sotto il califfato di ʿUmar."},
 badr:{titre:"Riferimento storico",texte:"La battaglia di Badr avvenne il 17 di Ramadan dell'anno 2 (624). Circa 313 musulmani affrontarono quasi 1000 combattenti dei Quraysh."},
 fath:{titre:"Riferimento storico",texte:"La Mecca fu aperta nel Ramadan dell'anno 8 (630), quasi senza combattere, da circa 10 000 musulmani. Il Profeta ﷺ concesse un perdono generale ai Meccani."},
 califes:{titre:"Riferimento storico",texte:"I quattro califfi ben guidati: Abû Bakr aṣ-Ṣiddîq (632-634), ʿUmar al-Fârûq (634-644), ʿUthmân Dhû n-Nûrayn (644-656), che sposò due figlie del Profeta ﷺ, Ruqayya e poi Umm Kulthûm, e ʿAlî (656-661), cugino del Profeta ﷺ e marito di sua figlia Fâṭima."}
},

/* Riassunti mostrati per gli hadith lunghi (il testo completo resta accessibile) */
resumes:{
 cinq:"Durante il Viaggio notturno (al-Isrâ' wa l-Miʿrâj), furono dapprima prescritte cinquanta preghiere, poi alleggerite fino a cinque preghiere al giorno.",
 enfants:"ar-Rubayyiʿ bint Muʿawwidh racconta che i Compagni facevano digiunare i loro bambini piccoli il giorno di ʿÂshûrâ', e davano loro giocattoli di lana per pazientare fino alla rottura del digiuno.",
 hira:"ʿÂ'isha racconta che il Profeta ﷺ si ritirava nella grotta di Hira. L'angelo venne e gli disse: «Leggi!». Tornò da Khadîja, che lo confortò e poi lo portò dal suo cugino Waraqa ibn Nawfal.",
 regles:"ʿÂ'isha spiega che veniva loro ordinato di recuperare il digiuno mancato durante il ciclo mestruale, ma non la preghiera.",
 tarawih:"Il Profeta ﷺ pregò di notte in moschea durante il Ramadan; alcune persone pregarono dietro di lui, sempre più numerose. Poi smise di uscire, temendo che questa preghiera fosse resa loro obbligatoria.",
 adhan:"Il Compagno ʿAbdallah ibn Zayd vide in sogno le parole dell'adhân. Il Profeta ﷺ confermò questo sogno e chiese a Bilâl di lanciare il richiamo, perché la sua voce arrivava più lontano.",
 ikhlas:"Un uomo recitava continuamente la sura Al-Ikhlâs e lo riteneva poca cosa. Il Profeta ﷺ disse: «Equivale a un terzo del Corano.»",
 kursi:"Il Profeta ﷺ chiese a Ubayy ibn Kaʿb quale fosse il versetto più grande del Libro di Allah. Rispose: Âyat al-Kursî. Il Profeta ﷺ si congratulò con lui per la sua scienza.",
 hajj_une:"Il Profeta ﷺ annunciò che il hajj era prescritto. Un uomo chiese: «Ogni anno?» Rispose che se avesse detto sì, sarebbe diventato obbligatorio ogni anno: è obbligatorio una volta.",
 arafa:"Alcune persone interrogarono il Profeta ﷺ ad ʿArafa sul pellegrinaggio. Rispose: «Il hajj è ʿArafa.»",
 jibril:"L'angelo Jibrîl, in forma umana, interrogò il Profeta ﷺ sull'islam, la fede e l'eccellenza. La fede (îmân): credere in Allah, nei Suoi angeli, nei Suoi libri, nei Suoi messaggeri, nell'Ultimo Giorno e nel destino, buono o cattivo.",
 vie:"Ibn ʿAbbâs riferisce che il Profeta ﷺ ricevette la rivelazione a 40 anni, restò 13 anni alla Mecca, emigrò a Medina dove visse 10 anni, e morì a 63 anni.",
 idoles:"Il giorno della conquista, c'erano 360 idoli intorno alla Kaaba. Il Profeta ﷺ li colpiva con un bastone recitando: «La verità è venuta e la falsità è svanita.»",
 compilation:"Dopo la battaglia della Yamâma, in cui furono uccisi molti recitatori, Abû Bakr incaricò Zayd ibn Thâbit di raccogliere il Corano in un'unica raccolta.",
 copies:"ʿUthmân, preoccupato per le differenze di recitazione tra le province, fece copiare la raccolta del Corano in diversi esemplari inviati in ogni regione.",
 fitr_but:"Ibn ʿAbbâs riferisce che il Profeta ﷺ ha prescritto la zakat al-fitr per purificare chi ha digiunato dalle parole futili e sconvenienti, e per nutrire i poveri.",
 afw:"ʿÂ'isha chiese cosa dire se avesse conosciuto la Notte del Destino. Egli rispose: «Di': Allâhumma innaka ʿafuwwun tuḥibbu l-ʿafwa faʿfu ʿannî» — O Allah, Tu sei Colui che perdona, ami il perdono, perdonami dunque."
}
};
